--
-- Name: account_rep(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_rep(p_account uuid) RETURNS TABLE(rep_number text, rep_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT m.rep_number, coalesce(u.name, u.email)
    FROM public.account_members m
    JOIN public.users u ON u.id = m.user_id
   WHERE m.account_id = p_account
     AND m.role = 'lead'
     AND m.removed_at IS NULL
   ORDER BY m.rep_number NULLS LAST
   LIMIT 1;
$$;


