--
-- Name: add_crew_member(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_crew_member(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_account uuid;
  v_role    text;
  v_user    uuid := (p->>'user_id')::uuid;
  v_existing public.account_members%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_account := public.my_account_id();
  IF v_account IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  IF NOT public.is_impersonating() THEN
    SELECT role INTO v_role FROM public.account_members
     WHERE user_id = v_caller AND removed_at IS NULL;
    IF v_role IS DISTINCT FROM 'lead' THEN
      RAISE EXCEPTION 'Only a lead can add crew members';
    END IF;
  END IF;

  IF v_user IS NULL THEN RAISE EXCEPTION 'user_id is required (their id from Auth → Users)'; END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_user) THEN
    RAISE EXCEPTION 'No such user. Invite them in Supabase first (Auth → Users → Invite user).';
  END IF;

  SELECT * INTO v_existing FROM public.account_members WHERE user_id = v_user;
  IF FOUND THEN
    IF v_existing.account_id = v_account AND v_existing.removed_at IS NOT NULL THEN
      UPDATE public.account_members
         SET removed_at = NULL, removed_by = NULL, removed_reason = NULL
       WHERE user_id = v_user;
      RETURN v_account;
    END IF;
    RAISE EXCEPTION 'That person already belongs to an account. Moving them is a data migration, not an invitation.';
  END IF;

  INSERT INTO public.users (id, email, name, credits)
  VALUES (v_user, p->>'email', nullif(btrim(coalesce(p->>'name','')), ''), 0)
  ON CONFLICT (id) DO UPDATE
    SET email = coalesce(EXCLUDED.email, public.users.email),
        name  = coalesce(EXCLUDED.name,  public.users.name);

  INSERT INTO public.account_members (user_id, account_id, role, desktop_access, rep_number, invited_by)
  VALUES (v_user, v_account, 'tech', false, NULL, v_caller);

  RETURN v_account;
END;
$$;


--
-- Name: add_subcontractor(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_subcontractor(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_real    uuid;
  v_role    text;
  v_parent_parent uuid;
  v_user    uuid := nullif(p->>'user_id', '')::uuid;
  v_email   text := nullif(btrim(coalesce(p->>'email', '')), '');
  v_name    text := nullif(btrim(coalesce(p->>'name', '')), '');
  v_rep     text := nullif(btrim(coalesce(p->>'rep_number', '')), '');
  v_credits integer := coalesce((p->>'credits')::integer, 0);
  v_account uuid;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  -- The REAL account, and not while acting as somebody else: creating a company
  -- under a company you are only borrowing is never what was meant.
  IF public.is_impersonating() THEN
    RAISE EXCEPTION 'Stop acting as another company before adding a subcontractor.';
  END IF;

  SELECT m.account_id, m.role INTO v_real, v_role
    FROM public.account_members m WHERE m.user_id = v_caller;
  IF v_real IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;
  IF v_role IS DISTINCT FROM 'lead' THEN
    RAISE EXCEPTION 'Only a lead can add a subcontractor';
  END IF;

  SELECT parent_account_id INTO v_parent_parent FROM public.accounts WHERE id = v_real;
  IF v_parent_parent IS NOT NULL THEN
    RAISE EXCEPTION 'Only the umbrella account can take on subcontractors. Add a crew member instead.';
  END IF;

  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Their user id is required — invite them in Supabase first, then copy it from Auth → Users.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_user) THEN
    RAISE EXCEPTION 'No such user. Invite them in Supabase first (Auth → Users → Invite user).';
  END IF;
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'A company name is required: it is what the account is called.';
  END IF;
  IF v_rep IS NULL THEN
    RAISE EXCEPTION 'Their technician number is required: it is what the certificate names.';
  END IF;

  -- Already somewhere in the system. Moving an existing account is a data
  -- migration — its records do not follow a membership — so it is refused here
  -- rather than half-done.
  IF EXISTS (SELECT 1 FROM public.account_members WHERE user_id = v_user) THEN
    RAISE EXCEPTION 'That person already belongs to an account. Moving them is a data migration, not an invitation.';
  END IF;

  v_account := public.create_subcontractor(v_user, coalesce(v_email, ''), v_name, v_rep, v_real, v_credits);

  RETURN json_build_object(
    'account_id', v_account,
    'name',       v_name,
    'rep_number', v_rep,
    'credits',    v_credits);
END;
$$;


--
-- Name: amend_fp_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.amend_fp_inspection(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := nullif(p->>'inspection_id','')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason','')), '');
  v_prev    public.fp_inspections%ROWTYPE;
  v_new     uuid;
  v_who     text;
  v_type_id uuid;
  v_type_nm text;
BEGIN
  -- A correction with no reason is indistinguishable from tampering six months
  -- later. It is the one field that cannot be skipped.
  IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why this record is being corrected'; END IF;

  SELECT * INTO v_prev FROM public.fp_inspections
   WHERE id = v_id AND account_id = v_account FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such inspection'; END IF;
  IF v_prev.is_deleted THEN RAISE EXCEPTION 'That record was deleted; restore it before correcting it'; END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  IF nullif(p->>'equipment_type','') IS NOT NULL THEN
    v_type_id := public.fp_type_for(v_account, p->>'equipment_type');
    SELECT name INTO v_type_nm FROM public.fp_equipment_types WHERE id = v_type_id;
  END IF;

  UPDATE public.fp_inspections SET is_current = false, updated_at = now() WHERE id = v_prev.id;

  INSERT INTO public.fp_inspections (
    account_id, asset_id, work_order_id, inspection_date, next_due_date,
    rep_number, tech_user_id, collected_by, collector_name,
    model_id, equipment_type_id, item_type, description, manufacturer, model,
    lot_number, mfg_month, mfg_year, status, nfc_tag_serial, tag_url,
    template_id, template_version, overall_pass, discard_reason, discard_note,
    version, supersedes, is_current, source, captured_at
  ) VALUES (
    v_account, v_prev.asset_id,
    coalesce(nullif(p->>'work_order_id',''), v_prev.work_order_id),
    coalesce((p->>'inspection_date')::date, v_prev.inspection_date),
    coalesce((p->>'next_due_date')::date, v_prev.next_due_date),
    v_prev.rep_number, v_prev.tech_user_id, v_prev.collected_by,
    -- Who COLLECTED it does not change because somebody corrected a typo. The
    -- corrector is recorded in the audit row, which is where they belong.
    v_prev.collector_name,
    v_prev.model_id, coalesce(v_type_id, v_prev.equipment_type_id),
    coalesce(v_type_nm, nullif(p->>'item_type',''), v_prev.item_type),
    coalesce(p->>'description', v_prev.description),
    coalesce(nullif(p->>'manufacturer',''), v_prev.manufacturer),
    coalesce(nullif(p->>'model',''), v_prev.model),
    coalesce(p->>'lot_number', v_prev.lot_number),
    coalesce((p->>'mfg_month')::integer, v_prev.mfg_month),
    coalesce((p->>'mfg_year')::integer, v_prev.mfg_year),
    v_prev.status, v_prev.nfc_tag_serial, v_prev.tag_url,
    v_prev.template_id, v_prev.template_version,
    v_prev.overall_pass, v_prev.discard_reason,
    coalesce(p->>'discard_note', v_prev.discard_note),
    v_prev.version + 1, v_prev.id, true,
    -- Recorded as a correction, so a certificate can never present an amended
    -- record as though a tech had answered the questions that way on the day.
    'office_amend',
    v_prev.captured_at
  )
  RETURNING id INTO v_new;

  -- The checks come across unchanged: this corrects the ITEM's details, not
  -- what the tech found. Changing an answer is re-inspecting, and that is a new
  -- inspection rather than an amendment.
  INSERT INTO public.fp_inspection_checks
    (fp_inspection_id, ord, code, prompt, answer, answer_style, pass_answer, result, source, note)
  SELECT v_new, ord, code, prompt, answer, answer_style, pass_answer, result, source, note
    FROM public.fp_inspection_checks WHERE fp_inspection_id = v_prev.id;

  INSERT INTO public.fp_record_audit
    (account_id, asset_id, inspection_id, action, reason, before, after, actor_id, actor_name)
  VALUES (v_account, v_prev.asset_id, v_new, 'amend', v_reason,
          row_to_json(v_prev)::jsonb,
          (SELECT row_to_json(i)::jsonb FROM public.fp_inspections i WHERE i.id = v_new),
          auth.uid(), v_who);

  RETURN (SELECT row_to_json(i) FROM public.fp_inspections i WHERE i.id = v_new);
END;
$$;


--
-- Name: amend_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.amend_inspection(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead_account();
  v_id      uuid := nullif(p->>'inspection_id','')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason','')), '');
  v_prev    public.inspections%ROWTYPE;
  v_new     uuid;
  v_who     text;
BEGIN
  IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why this record is being corrected'; END IF;

  SELECT * INTO v_prev FROM public.inspections
   WHERE id = v_id AND account_id = v_account FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such inspection'; END IF;
  IF v_prev.is_deleted THEN RAISE EXCEPTION 'That record was deleted; restore it before correcting it'; END IF;
  IF NOT v_prev.is_current THEN RAISE EXCEPTION 'That is a superseded version; correct the current one'; END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  UPDATE public.inspections SET is_current = false, updated_at = now() WHERE id = v_prev.id;

  INSERT INTO public.inspections (
    serial_num, inspection_date, tech_name, work_order_id, next_due_date, notes,
    brand, type, length, account_id, asset_id, tech_user_id,
    version, supersedes, is_current, source, captured_at,
    lubricated, has_leveler, has_claw, has_vrung,
    rep_number, collected_by, collector_name, parts,
    -- Deliberately NOT carried over. The new version has not been to BSI,
    -- whatever happened to the one it replaces — that is the whole point of
    -- the orange state.
    bsi_pushed_at, bsi_box_ref
  ) VALUES (
    coalesce(nullif(p->>'serial_num',''), v_prev.serial_num),
    coalesce((p->>'inspection_date')::date, v_prev.inspection_date),
    v_prev.tech_name,
    coalesce(nullif(p->>'work_order_id',''), v_prev.work_order_id),
    coalesce((p->>'next_due_date')::date, v_prev.next_due_date),
    coalesce(p->>'notes',  v_prev.notes),
    coalesce(nullif(p->>'brand',''),  v_prev.brand),
    coalesce(nullif(p->>'type',''),   v_prev.type),
    coalesce(nullif(p->>'length',''), v_prev.length),
    v_account, v_prev.asset_id, v_prev.tech_user_id,
    v_prev.version + 1, v_prev.id, true,
    'office_amend',
    v_prev.captured_at,
    -- A flag is tri-state: absent from the payload means "leave it alone",
    -- and null means "the tech did not assess this". `p ? 'key'` tells the
    -- two apart, which coalesce cannot.
    CASE WHEN p ? 'lubricated'  THEN (p->>'lubricated')::boolean  ELSE v_prev.lubricated  END,
    CASE WHEN p ? 'has_leveler' THEN (p->>'has_leveler')::boolean ELSE v_prev.has_leveler END,
    CASE WHEN p ? 'has_claw'    THEN (p->>'has_claw')::boolean    ELSE v_prev.has_claw    END,
    CASE WHEN p ? 'has_vrung'   THEN (p->>'has_vrung')::boolean   ELSE v_prev.has_vrung   END,
    v_prev.rep_number, v_prev.collected_by, v_prev.collector_name,
    CASE WHEN p ? 'parts' THEN p->'parts' ELSE v_prev.parts END,
    NULL, NULL
  )
  RETURNING id INTO v_new;

  INSERT INTO public.inspection_audit
    (account_id, inspection_id, serial_num, action, reason, before, after, actor_id, actor_name)
  VALUES (v_account, v_new, v_prev.serial_num, 'amend', v_reason,
          row_to_json(v_prev)::jsonb,
          (SELECT row_to_json(i)::jsonb FROM public.inspections i WHERE i.id = v_new),
          auth.uid(), v_who);

  RETURN (SELECT row_to_json(i) FROM public.inspections i WHERE i.id = v_new);
END;
$$;


--
-- Name: can_see(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_account IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.visible_account_ids() v WHERE v.account_id = p_account);
$$;


--
-- Name: can_use_catalog(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_use_catalog(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_account IS NULL
      OR EXISTS (SELECT 1 FROM public.catalog_account_ids() c WHERE c.account_id = p_account);
$$;


--
-- Name: catalog_account_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_account_ids() RETURNS TABLE(account_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT a.account_id FROM public.account_ancestors(public.my_account_id()) a;
$$;


--
-- Name: certificate_url(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.certificate_url(p_public_ref text, p_kind text DEFAULT 'ladder'::text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN p_public_ref IS NULL THEN NULL ELSE
    (SELECT value FROM public.app_settings WHERE key = 'certificate_base_url')
    || CASE WHEN p_kind = 'fall_protection' THEN '/fp/?t=' ELSE '/?t=' END
    || p_public_ref
  END;
$$;


--
-- Name: certificate_view_summary(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.certificate_view_summary(p_days integer DEFAULT 30) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_dev     boolean := public.is_developer();
  v_since   timestamptz := now() - (greatest(1, least(coalesce(p_days, 30), 365)) || ' days')::interval;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  RETURN json_build_object(
    'since', v_since,
    'by_viewer', (
      SELECT coalesce(json_agg(x), '[]'::json) FROM (
        SELECT viewer_kind, network_label,
               sum(hits)::int AS hits, count(*)::int AS sessions,
               count(DISTINCT coalesce(public_ref, serial_key))::int AS items
          FROM public.certificate_views
         WHERE last_seen_at >= v_since AND (v_dev OR account_id = v_account)
         GROUP BY viewer_kind, network_label
         ORDER BY sum(hits) DESC
      ) x),
    'by_day', (
      SELECT coalesce(json_agg(x ORDER BY x.day), '[]'::json) FROM (
        SELECT date_trunc('day', last_seen_at)::date AS day, sum(hits)::int AS hits
          FROM public.certificate_views
         WHERE last_seen_at >= v_since AND (v_dev OR account_id = v_account)
         GROUP BY 1
      ) x),
    'top_items', (
      SELECT coalesce(json_agg(x), '[]'::json) FROM (
        SELECT v.public_ref, coalesce(a.serial_raw, v.serial_key) AS serial_num,
               v.kind, sum(v.hits)::int AS hits, max(v.last_seen_at) AS last_viewed
          FROM public.certificate_views v
          LEFT JOIN public.assets a ON a.id = v.asset_id
         WHERE v.last_seen_at >= v_since AND (v_dev OR v.account_id = v_account)
         GROUP BY v.public_ref, coalesce(a.serial_raw, v.serial_key), v.kind
         ORDER BY sum(v.hits) DESC
         LIMIT 25
      ) x),
    -- Tags pointing at something this database does not have. Each one is a
    -- physical tag in the world that resolves to nothing.
    -- `v.found` is qualified because FOUND is also plpgsql's own status
    -- variable, and an unqualified reference is ambiguous inside a function.
    'misses', (
      SELECT coalesce(json_agg(x), '[]'::json) FROM (
        SELECT v.public_ref, v.serial_key, sum(v.hits)::int AS hits,
               max(v.last_seen_at) AS last_seen
          FROM public.certificate_views v
         WHERE v.last_seen_at >= v_since AND NOT v.found
           AND (v_dev OR v.account_id IS NULL OR v.account_id = v_account)
         GROUP BY v.public_ref, v.serial_key
         ORDER BY max(v.last_seen_at) DESC
         LIMIT 25
      ) x)
  );
END;
$$;


--
-- Name: certificate_views_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.certificate_views_for(p_public_ref text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.my_account_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN (
    SELECT coalesce(json_agg(x ORDER BY x.last_seen_at DESC), '[]'::json) FROM (
      SELECT viewer_kind, network_label, device_class, lookup_by, hits,
             first_seen_at, last_seen_at, tz
        FROM public.certificate_views
       WHERE public_ref = upper(p_public_ref)
         AND (public.is_developer() OR account_id = v_account)
       LIMIT 200
    ) x);
END;
$$;


--
-- Name: charge_work_order(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.charge_work_order(p_wo_number text, p_scope text DEFAULT 'ladder'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id    uuid := auth.uid();
  v_account_id uuid;
  v_key        text;
  v_credits    integer;
  v_new        integer;
  v_wo_id      uuid;
  v_charged_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_key := public.wo_key(p_wo_number);
  IF v_key = '' THEN RAISE EXCEPTION 'A work order number is required'; END IF;

  -- Follows the account being acted as; identical when not impersonating.
  v_account_id := public.my_account_id();
  IF v_account_id IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  -- Lock the account row first. Two imports finishing at the same moment must
  -- not both read the same balance and both debit it.
  SELECT credits INTO v_credits FROM public.accounts WHERE id = v_account_id FOR UPDATE;

  INSERT INTO public.work_orders (account_id, wo_number, wo_key, scope, created_by)
  VALUES (v_account_id, p_wo_number, v_key, p_scope, v_user_id)
  ON CONFLICT (account_id, wo_key) DO NOTHING
  RETURNING id INTO v_wo_id;

  IF v_wo_id IS NULL THEN
    SELECT id, charged_at INTO v_wo_id, v_charged_at
    FROM public.work_orders WHERE account_id = v_account_id AND wo_key = v_key;
  END IF;

  -- Already paid for. This is the whole point: edits, re-runs, and merging more
  -- techs' data into an existing work order are free.
  IF v_charged_at IS NOT NULL THEN
    RETURN json_build_object(
      'charged', false, 'reason', 'already_paid',
      'credits', v_credits, 'work_order_id', v_wo_id
    );
  END IF;

  IF v_credits = -1 THEN
    UPDATE public.work_orders
       SET charged_at = now(), charged_by = v_user_id, credits_charged = 0, updated_at = now()
     WHERE id = v_wo_id;
    INSERT INTO public.usage_log(user_id, account_id, work_order_id, work_order_uuid, credits_before, credits_after)
    VALUES (v_user_id, v_account_id, p_wo_number, v_wo_id, -1, -1);
    RETURN json_build_object('charged', true, 'credits', -1, 'work_order_id', v_wo_id);
  END IF;

  IF v_credits <= 0 THEN
    RAISE EXCEPTION 'No import credits remaining — contact your administrator';
  END IF;

  v_new := v_credits - 1;
  UPDATE public.accounts SET credits = v_new WHERE id = v_account_id;
  UPDATE public.work_orders
     SET charged_at = now(), charged_by = v_user_id, credits_charged = 1, updated_at = now()
   WHERE id = v_wo_id;

  INSERT INTO public.usage_log(user_id, account_id, work_order_id, work_order_uuid, credits_before, credits_after)
  VALUES (v_user_id, v_account_id, p_wo_number, v_wo_id, v_credits, v_new);

  RETURN json_build_object('charged', true, 'credits', v_new, 'work_order_id', v_wo_id);
END;
$$;


--
-- Name: close_job(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_job(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := (p->>'job_id')::uuid;
  v_status  text := coalesce(p->>'status', 'closed');
BEGIN
  IF v_status NOT IN ('open', 'closed', 'cancelled') THEN
    RAISE EXCEPTION 'Unknown status: %', v_status;
  END IF;
  UPDATE public.jobs SET
    status     = v_status,
    close_note = CASE WHEN v_status = 'open' THEN NULL ELSE nullif(p->>'note', '') END,
    closed_at  = CASE WHEN v_status = 'open' THEN NULL ELSE now() END,
    closed_by  = CASE WHEN v_status = 'open' THEN NULL ELSE auth.uid() END,
    updated_at = now()
   WHERE id = v_id AND account_id = v_account;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such job'; END IF;
  RETURN public.job_detail(v_id);
END;
$$;


--
-- Name: consolidate_to_one_account(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consolidate_to_one_account(p_lead_user uuid, p_account_name text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_keep     uuid;
  v_credits  integer;
  v_unlimited boolean;
  v_moved    integer;
  v_adopted  integer;
  v_fp       integer;
  v_dropped  integer;
BEGIN
  SELECT account_id INTO v_keep FROM public.account_members WHERE user_id = p_lead_user;
  IF v_keep IS NULL THEN
    RAISE EXCEPTION 'That user has no account — run create_lia_user for them first';
  END IF;

  -- Credits: unlimited anywhere wins, otherwise sum them. Summing is the
  -- conservative choice — these balances were bought.
  SELECT bool_or(credits = -1), sum(GREATEST(credits, 0))
    INTO v_unlimited, v_credits FROM public.accounts;

  UPDATE public.accounts
     SET credits = CASE WHEN v_unlimited THEN -1 ELSE coalesce(v_credits, 0) END,
         name = coalesce(nullif(p_account_name, ''), name)
   WHERE id = v_keep;

  -- Everyone joins it. The nominated user leads; everyone else collects.
  UPDATE public.account_members
     SET account_id = v_keep,
         role = CASE WHEN user_id = p_lead_user THEN 'lead' ELSE 'tech' END,
         desktop_access = (user_id = p_lead_user)
   WHERE account_id <> v_keep OR user_id = p_lead_user;
  GET DIAGNOSTICS v_moved = ROW_COUNT;

  -- Everything the backfill either attributed elsewhere or could not place.
  UPDATE public.assets SET account_id = v_keep WHERE account_id IS DISTINCT FROM v_keep;
  UPDATE public.inspections SET account_id = v_keep WHERE account_id IS DISTINCT FROM v_keep;
  GET DIAGNOSTICS v_adopted = ROW_COUNT;
  UPDATE public.fp_inspections SET account_id = v_keep WHERE account_id IS DISTINCT FROM v_keep;
  GET DIAGNOSTICS v_fp = ROW_COUNT;
  -- Work orders are unique on (account, wo_key), and two accounts may each hold
  -- the same number — that namespacing is the point of the constraint. Merging
  -- them makes those collide, so fold duplicates instead of failing: keep the
  -- row that was actually charged (earliest wins on a tie), re-point everything
  -- at it, and drop the loser. Never charge twice for what is now one order.
  UPDATE public.work_orders w SET account_id = v_keep
   WHERE w.account_id IS DISTINCT FROM v_keep
     AND NOT EXISTS (SELECT 1 FROM public.work_orders k
                      WHERE k.account_id = v_keep AND k.wo_key = w.wo_key);

  WITH survivors AS (
    SELECT DISTINCT ON (wo_key) wo_key, id
      FROM public.work_orders
     WHERE account_id = v_keep OR account_id IS DISTINCT FROM v_keep
     ORDER BY wo_key, (charged_at IS NULL), charged_at NULLS LAST, created_at, id
  ), losers AS (
    SELECT w.id, s.id AS keep_id
      FROM public.work_orders w JOIN survivors s ON s.wo_key = w.wo_key
     WHERE w.id <> s.id
  )
  UPDATE public.usage_log u SET work_order_uuid = l.keep_id
    FROM losers l WHERE u.work_order_uuid = l.id;

  WITH survivors AS (
    SELECT DISTINCT ON (wo_key) wo_key, id
      FROM public.work_orders
     ORDER BY wo_key, (charged_at IS NULL), charged_at NULLS LAST, created_at, id
  ), losers AS (
    SELECT w.id, s.id AS keep_id
      FROM public.work_orders w JOIN survivors s ON s.wo_key = w.wo_key
     WHERE w.id <> s.id
  )
  UPDATE public.inspections i SET work_order_uuid = l.keep_id
    FROM losers l WHERE i.work_order_uuid = l.id;

  WITH survivors AS (
    SELECT DISTINCT ON (wo_key) wo_key, id
      FROM public.work_orders
     ORDER BY wo_key, (charged_at IS NULL), charged_at NULLS LAST, created_at, id
  )
  DELETE FROM public.work_orders w
   USING survivors s
   WHERE s.wo_key = w.wo_key AND w.id <> s.id;

  UPDATE public.work_orders SET account_id = v_keep WHERE account_id IS DISTINCT FROM v_keep;
  UPDATE public.usage_log SET account_id = v_keep WHERE account_id IS DISTINCT FROM v_keep;
  UPDATE public.fp_models SET account_id = v_keep WHERE account_id IS NOT NULL AND account_id <> v_keep;

  -- An asset's identity is (account, kind, serial), so consolidating can create
  -- duplicates that were legitimately distinct before. Fold them together.
  WITH ranked AS (
    SELECT id, kind, serial_key,
           first_value(id) OVER (PARTITION BY kind, serial_key ORDER BY created_at, id) AS keep_id
      FROM public.assets WHERE account_id = v_keep
  )
  UPDATE public.inspections i SET asset_id = r.keep_id
    FROM ranked r WHERE i.asset_id = r.id AND r.id <> r.keep_id;

  WITH ranked AS (
    SELECT id, kind, serial_key,
           first_value(id) OVER (PARTITION BY kind, serial_key ORDER BY created_at, id) AS keep_id
      FROM public.assets WHERE account_id = v_keep
  )
  UPDATE public.fp_inspections f SET asset_id = r.keep_id
    FROM ranked r WHERE f.asset_id = r.id AND r.id <> r.keep_id;

  DELETE FROM public.assets a
   WHERE a.account_id = v_keep
     AND NOT EXISTS (SELECT 1 FROM public.inspections i WHERE i.asset_id = a.id)
     AND NOT EXISTS (SELECT 1 FROM public.fp_inspections f WHERE f.asset_id = a.id);

  -- Two inspections of the same item on the same day can now collide on the
  -- partial unique index. Keep the newest as current and supersede the rest,
  -- which is exactly what a second capture would have done anyway.
  WITH dupes AS (
    SELECT id, row_number() OVER (PARTITION BY asset_id, inspection_date
                                  ORDER BY created_at DESC, id DESC) AS rn
      FROM public.inspections WHERE is_current AND NOT is_deleted
  )
  UPDATE public.inspections i SET is_current = false, updated_at = now()
    FROM dupes d WHERE i.id = d.id AND d.rn > 1;

  DELETE FROM public.accounts
   WHERE id <> v_keep
     AND NOT EXISTS (SELECT 1 FROM public.account_members m WHERE m.account_id = accounts.id);
  GET DIAGNOSTICS v_dropped = ROW_COUNT;

  RETURN json_build_object(
    'account_id',        v_keep,
    'members',           v_moved,
    'inspections_moved', v_adopted,
    'fp_moved',          v_fp,
    'accounts_removed',  v_dropped,
    'credits',           (SELECT credits FROM public.accounts WHERE id = v_keep)
  );
END;
$$;


--
-- Name: consume_credit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_credit(p_work_order_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result json;
BEGIN
  -- Older builds send the literal 'unknown' when the work order box was left
  -- blank. Under (account_id, wo_key) uniqueness that would become a single
  -- shared bucket: the first blank-WO import charges and every one after it is
  -- free forever. Refuse it rather than leak imports.
  IF public.wo_key(p_work_order_id) IN ('', 'UNKNOWN') THEN
    RAISE EXCEPTION 'A work order number is required. Enter the real work order number, or update Lia Office.';
  END IF;

  v_result := public.charge_work_order(p_work_order_id, 'ladder');
  RETURN (v_result->>'credits')::integer;
END;
$$;


--
-- Name: FUNCTION consume_credit(p_work_order_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.consume_credit(p_work_order_id text) IS 'DEPRECATED — use charge_work_order(). Kept for older Lia Office builds still in the field.';


--
-- Name: create_lia_user(uuid, text, text, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lia_user(p_id uuid, p_email text, p_name text DEFAULT NULL::text, p_credits integer DEFAULT 0, p_account_id uuid DEFAULT NULL::uuid, p_role text DEFAULT 'lead'::text, p_rep_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid;
BEGIN
  INSERT INTO public.users(id, email, name, credits)
  VALUES (p_id, p_email, p_name, p_credits)
  ON CONFLICT (id) DO UPDATE
    SET email = EXCLUDED.email, name = EXCLUDED.name, credits = EXCLUDED.credits;

  SELECT account_id INTO v_account FROM public.account_members WHERE user_id = p_id;

  IF v_account IS NULL THEN
    IF p_account_id IS NOT NULL THEN
      v_account := p_account_id;
    ELSE
      INSERT INTO public.accounts (name, credits)
      VALUES (coalesce(nullif(p_name, ''), p_email), p_credits)
      RETURNING id INTO v_account;
    END IF;

    INSERT INTO public.account_members (user_id, account_id, role, desktop_access)
    VALUES (p_id, v_account, coalesce(p_role, 'lead'),
            coalesce(p_role, 'lead') = 'lead')
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  -- Only set on a new membership or when explicitly supplied, so re-running
  -- provisioning cannot silently clear a rep number.
  IF p_rep_number IS NOT NULL THEN
    UPDATE public.account_members SET rep_number = p_rep_number WHERE user_id = p_id;
  END IF;

  RETURN v_account;
END;
$$;


--
-- Name: create_subcontractor(uuid, text, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_subcontractor(p_user_id uuid, p_email text, p_name text, p_rep_number text, p_parent uuid, p_credits integer DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid;
  v_existing uuid;
BEGIN
  IF p_rep_number IS NULL OR btrim(p_rep_number) = '' THEN
    RAISE EXCEPTION 'A lead subcontractor needs their technician number: it is what the certificate names.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'No auth.users row for % — invite them first.', p_user_id;
  END IF;
  IF p_parent IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.accounts WHERE id = p_parent) THEN
    RAISE EXCEPTION 'Umbrella account % does not exist.', p_parent;
  END IF;

  SELECT account_id INTO v_existing FROM public.account_members WHERE user_id = p_user_id;

  IF v_existing IS NULL THEN
    INSERT INTO public.accounts (name, credits, parent_account_id)
    VALUES (coalesce(nullif(btrim(p_name), ''), p_email), p_credits, p_parent)
    RETURNING id INTO v_account;

    INSERT INTO public.users (id, email, name, credits)
    VALUES (p_user_id, p_email, p_name, 0)
    ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email, name = EXCLUDED.name;

    INSERT INTO public.account_members (user_id, account_id, role, desktop_access, rep_number)
    VALUES (p_user_id, v_account, 'lead', true, btrim(p_rep_number));
  ELSE
    -- Already provisioned. Settle the parts this call is authoritative for and
    -- leave the account where it is: moving an account that already holds work
    -- is a data migration, not a provisioning call.
    v_account := v_existing;
    UPDATE public.account_members
       SET role = 'lead', desktop_access = true, rep_number = btrim(p_rep_number)
     WHERE user_id = p_user_id;
    UPDATE public.accounts SET parent_account_id = p_parent
     WHERE id = v_account AND parent_account_id IS NULL AND p_parent IS NOT NULL;
  END IF;

  RETURN v_account;
END;
$$;


--
-- Name: delete_fp_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_fp_inspection(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := nullif(p->>'inspection_id','')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason','')), '');
  v_row     public.fp_inspections%ROWTYPE;
  v_who     text;
BEGIN
  IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why this record is being deleted'; END IF;

  SELECT * INTO v_row FROM public.fp_inspections
   WHERE id = v_id AND account_id = v_account FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such inspection'; END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  UPDATE public.fp_inspections
     SET is_deleted = true, is_current = false, updated_at = now()
   WHERE id = v_id;

  -- `is_current` is per inspection DATE, not per item — the unique index is
  -- (asset_id, inspection_date). So deleting a record restores the previous
  -- VERSION of that same date, if there is one. Other dates are already current
  -- in their own right and must not be touched: promoting last year's record
  -- here would leave the item with two current rows for one date's worth of
  -- work and quietly change what every other query returns.
  UPDATE public.fp_inspections SET is_current = true, updated_at = now()
   WHERE id = (SELECT i.id FROM public.fp_inspections i
                WHERE i.asset_id = v_row.asset_id
                  AND i.inspection_date = v_row.inspection_date
                  AND NOT i.is_deleted AND i.id <> v_id
                ORDER BY i.version DESC LIMIT 1);

  INSERT INTO public.fp_record_audit
    (account_id, asset_id, inspection_id, action, reason, before, actor_id, actor_name)
  VALUES (v_account, v_row.asset_id, v_id, 'delete', v_reason,
          row_to_json(v_row)::jsonb, auth.uid(), v_who);

  RETURN json_build_object('deleted', v_id, 'asset_id', v_row.asset_id);
END;
$$;


--
-- Name: delete_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_inspection(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead_account();
  v_id      uuid := nullif(p->>'inspection_id','')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason','')), '');
  v_prev    public.inspections%ROWTYPE;
  v_who     text;
  v_back    uuid;
BEGIN
  IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why this record is being deleted'; END IF;

  SELECT * INTO v_prev FROM public.inspections
   WHERE id = v_id AND account_id = v_account FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such inspection'; END IF;
  IF v_prev.is_deleted THEN RETURN (SELECT row_to_json(i) FROM public.inspections i WHERE i.id = v_id); END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  UPDATE public.inspections
     SET is_deleted = true, is_current = false, updated_at = now()
   WHERE id = v_prev.id;

  SELECT id INTO v_back FROM public.inspections
   WHERE account_id = v_account AND asset_id IS NOT DISTINCT FROM v_prev.asset_id
     AND serial_num = v_prev.serial_num
     AND inspection_date = v_prev.inspection_date
     AND NOT is_deleted AND id <> v_prev.id
   ORDER BY version DESC LIMIT 1;
  IF v_back IS NOT NULL THEN
    UPDATE public.inspections SET is_current = true, updated_at = now() WHERE id = v_back;
  END IF;

  INSERT INTO public.inspection_audit
    (account_id, inspection_id, serial_num, action, reason, before, after, actor_id, actor_name)
  VALUES (v_account, v_prev.id, v_prev.serial_num, 'delete', v_reason,
          row_to_json(v_prev)::jsonb, NULL, auth.uid(), v_who);

  RETURN json_build_object('deleted', v_prev.id, 'promoted', v_back);
END;
$$;


--
-- Name: delete_job(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_job(p jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_n       integer;
BEGIN
  DELETE FROM public.jobs WHERE id = (p->>'job_id')::uuid AND account_id = v_account;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: delete_known_network(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_known_network(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.account_members
                  WHERE user_id = auth.uid() AND role = 'lead') THEN
    RAISE EXCEPTION 'Only a lead technician can label networks';
  END IF;
  DELETE FROM public.known_networks
   WHERE id = p_id AND account_id = public.my_account_id();
END;
$$;


--
-- Name: developer_support_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.developer_support_counts() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_developer() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  RETURN (SELECT json_build_object(
    'unread',   count(*) FILTER (WHERE unread_developer),
    'open',     count(*) FILTER (WHERE status IN ('new','open','answered')),
    'blocking', count(*) FILTER (WHERE severity = 'blocking'
                                   AND status IN ('new','open','answered')),
    'total',    count(*))
    FROM public.support_tickets);
END;
$$;


--
-- Name: developer_support_inbox(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.developer_support_inbox(p_status text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_out json;
BEGIN
  IF NOT public.is_developer() THEN RAISE EXCEPTION 'Not authorized'; END IF;

  SELECT coalesce(json_agg(t), '[]'::json) INTO v_out FROM (
    SELECT s.id, s.ref, s.kind, s.severity, s.subject, s.status,
           s.reporter_name, s.reporter_email, s.account_id,
           (SELECT a.name FROM public.accounts a WHERE a.id = s.account_id) AS account_name,
           s.app, s.app_version, s.platform, s.screen, s.device,
           s.created_at, s.last_message_at, s.unread_developer,
           (SELECT coalesce(json_agg(json_build_object(
                     'id', m.id, 'author_role', m.author_role,
                     'author_name', m.author_name, 'body', m.body,
                     'created_at', m.created_at) ORDER BY m.created_at), '[]'::json)
              FROM public.support_messages m WHERE m.ticket_id = s.id) AS messages
      FROM public.support_tickets s
     WHERE (p_status IS NULL
            OR (p_status = 'open'   AND s.status IN ('new','open','answered'))
            OR (p_status = 'closed' AND s.status IN ('resolved','wont_fix'))
            OR s.status = p_status)
     ORDER BY
       CASE s.severity WHEN 'blocking' THEN 0 WHEN 'annoying' THEN 1 ELSE 2 END,
       s.unread_developer DESC,
       s.last_message_at DESC
  ) t;

  RETURN v_out;
END;
$$;


--
-- Name: device_class(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_class(p_ua text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_ua IS NULL OR p_ua = '' THEN 'unknown'
    WHEN p_ua ~* '(bot|crawler|spider|slurp|curl|wget|headless|preview)' THEN 'bot'
    WHEN p_ua ~* '(ipad|tablet|playbook|silk)' THEN 'tablet'
    WHEN p_ua ~* '(mobi|iphone|ipod|android.*mobile|windows phone)' THEN 'mobile'
    ELSE 'desktop'
  END;
$$;


--
-- Name: expired_photos(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expired_photos(p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, storage_path text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id, storage_path FROM public.inspection_photos
   WHERE expires_at IS NOT NULL AND expires_at <= now()
   ORDER BY expires_at LIMIT p_limit;
$$;


--
-- Name: field_work_orders(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_work_orders(p_archived boolean DEFAULT false) RETURNS TABLE(work_order_id text, scope text, total integer, pushed integer, stale integer, processed_at timestamp with time zone, last_captured_at timestamp with time zone, archived_at timestamp with time zone, archived_by_name text, techs json, state text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.my_account_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN QUERY
  WITH rec AS (
    SELECT i.work_order_id AS wo, 'ladder'::text AS sc, i.bsi_pushed_at,
           i.captured_at, i.collector_name AS who, i.supersedes
      FROM public.inspections i
     WHERE public.can_see(i.account_id) AND i.account_id = v_account
       AND i.is_current AND NOT i.is_deleted AND i.work_order_id IS NOT NULL
    UNION ALL
    SELECT f.work_order_id, 'fall_protection', f.bsi_pushed_at,
           f.captured_at, f.collector_name, f.supersedes
      FROM public.fp_inspections f
     WHERE public.can_see(f.account_id) AND f.account_id = v_account
       AND f.is_current AND NOT f.is_deleted AND f.work_order_id IS NOT NULL
  ),
  agg AS (
    SELECT r.wo,
           string_agg(DISTINCT r.sc, ',' ORDER BY r.sc)          AS scopes,
           count(*)::integer                                     AS total,
           count(r.bsi_pushed_at)::integer                       AS pushed,
           -- Superseding a record that had been pushed is the case the
           -- importer cannot repair by re-running.
           count(*) FILTER (WHERE r.bsi_pushed_at IS NULL
                              AND r.supersedes IS NOT NULL)::integer AS stale,
           max(r.bsi_pushed_at)                                  AS processed_at,
           max(r.captured_at)                                    AS last_captured_at,
           coalesce(json_agg(DISTINCT r.who) FILTER (WHERE r.who IS NOT NULL), '[]'::json) AS techs
      FROM rec r GROUP BY r.wo
  )
  SELECT a.wo, a.scopes, a.total, a.pushed, a.stale,
         a.processed_at, a.last_captured_at,
         w.archived_at,
         (SELECT coalesce(u.name, u.email) FROM public.users u WHERE u.id = w.archived_by),
         a.techs,
         CASE WHEN a.pushed = 0        THEN 'needs_processing'
              WHEN a.stale  > 0        THEN 'needs_bsi_edit'
              WHEN a.pushed < a.total  THEN 'has_edits'
              ELSE                          'processed' END
    FROM agg a
    LEFT JOIN public.work_orders w
           ON w.account_id = v_account AND w.wo_key = public.wo_key(a.wo)
   WHERE (w.archived_at IS NOT NULL) = p_archived
   ORDER BY coalesce(a.last_captured_at, a.processed_at) DESC;
END;
$$;


--
-- Name: fp_checks_for_authoring(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_checks_for_authoring(p_model_id uuid) RETURNS TABLE(ord integer, code text, prompt text, answer_style text, pass_answer boolean, required boolean, inherited boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_own uuid; v_type uuid; v_account uuid;
BEGIN
  -- SECURITY DEFINER bypasses RLS, so the account check has to be explicit.
  -- Without it any authenticated tech could pass another account's model id and
  -- read its checklists.
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT account_id INTO v_account FROM public.account_members WHERE user_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fp_models
                  WHERE id = p_model_id
                    AND (account_id = v_account OR account_id IS NULL)) THEN
    RAISE EXCEPTION 'That model is not on your account';
  END IF;

  SELECT id INTO v_own FROM public.fp_check_templates
   WHERE model_id = p_model_id AND published_at IS NOT NULL
   ORDER BY version DESC LIMIT 1;

  IF v_own IS NOT NULL THEN
    RETURN QUERY
      SELECT c.ord, c.code, c.prompt, c.answer_style, c.pass_answer, c.required, false
        FROM public.fp_template_checks c WHERE c.template_id = v_own ORDER BY c.ord;
    RETURN;
  END IF;

  -- No list of its own — fall back to the type the catalogue entry names.
  SELECT public.fp_type_for(v_account, m.item_type) INTO v_type
    FROM public.fp_models m WHERE m.id = p_model_id;

  RETURN QUERY
    SELECT c.ord, c.code, c.prompt, c.answer_style, c.pass_answer, c.required, true
      FROM public.fp_template_checks c
     WHERE c.template_id = public.fp_current_template(NULL, v_type)
     ORDER BY c.ord;
END;
$$;


--
-- Name: fp_current_checks(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_current_checks(p_model_id uuid DEFAULT NULL::uuid, p_equipment_type_id uuid DEFAULT NULL::uuid) RETURNS TABLE(template_id uuid, version integer, ord integer, code text, prompt text, answer_style text, pass_answer boolean, required boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT t.id, t.version, c.ord, c.code, c.prompt, c.answer_style, c.pass_answer, c.required
    FROM public.fp_check_templates t
    JOIN public.fp_template_checks c ON c.template_id = t.id
   WHERE t.id = public.fp_current_template(p_model_id, p_equipment_type_id)
   ORDER BY c.ord;
$$;


--
-- Name: fp_current_template(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_current_template(p_model_id uuid DEFAULT NULL::uuid, p_equipment_type_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    -- The model's own list, if it has been given one.
    (SELECT id FROM public.fp_check_templates
      WHERE p_model_id IS NOT NULL AND model_id = p_model_id AND published_at IS NOT NULL
      ORDER BY version DESC LIMIT 1),
    -- Otherwise the type's.
    (SELECT id FROM public.fp_check_templates
      WHERE p_equipment_type_id IS NOT NULL AND equipment_type_id = p_equipment_type_id
        AND published_at IS NOT NULL
      ORDER BY version DESC LIMIT 1));
$$;


--
-- Name: fp_default_status(boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_default_status(p_overall_pass boolean, p_recorded text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_recorded = 'inspection overdue' THEN 'inspection overdue'
    WHEN p_overall_pass IS false THEN 'fail'
    ELSE 'pass'
  END;
$$;


--
-- Name: fp_effective_status(boolean, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_effective_status(p_overall_pass boolean, p_next_due date, p_recorded text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    -- A failed item is failed for good. It does not become merely "overdue"
    -- once its due date passes.
    WHEN p_overall_pass IS false OR p_recorded = 'fail' THEN 'fail'
    WHEN p_next_due IS NOT NULL AND p_next_due < current_date THEN 'inspection overdue'
    ELSE 'pass'
  END;
$$;


--
-- Name: fp_find_asset(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_find_asset(p_value text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_v       text := btrim(coalesce(p_value, ''));
  v_asset   public.assets%ROWTYPE;
  v_by      text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_v = '' THEN RETURN NULL; END IF;

  IF v_v ~* '^https?://' THEN
    SELECT * INTO v_asset FROM public.assets
     WHERE account_id = v_account AND tag_url_key = public.fp_tag_url_key(v_v) LIMIT 1;
    IF FOUND THEN RETURN json_build_object('by','tag_url','asset',row_to_json(v_asset)); END IF;
    -- Our own certificate link still resolves by what is inside it.
    v_v := coalesce(substring(v_v from '[?&]t=([A-Za-z0-9]+)'),
                    substring(v_v from '[?&]s=([^&#]+)'), '');
    IF v_v = '' THEN RETURN NULL; END IF;
  END IF;

  SELECT * INTO v_asset FROM public.assets
   WHERE account_id = v_account AND serial_key = public.serial_key(v_v) LIMIT 1;
  IF FOUND THEN RETURN json_build_object('by','serial','asset',row_to_json(v_asset)); END IF;

  SELECT * INTO v_asset FROM public.assets
   WHERE account_id = v_account AND tag_label_key = public.serial_key(v_v)
     AND tag_label_key <> '' LIMIT 1;
  IF FOUND THEN RETURN json_build_object('by','tag_label','asset',row_to_json(v_asset)); END IF;

  SELECT * INTO v_asset FROM public.assets
   WHERE account_id = v_account AND public_ref = upper(v_v) LIMIT 1;
  IF FOUND THEN RETURN json_build_object('by','public_ref','asset',row_to_json(v_asset)); END IF;

  -- Ordered, not arbitrary. record_fp_tag_write refuses to create a duplicate
  -- chip id, but rows that predate that guard may already carry one, and a bare
  -- LIMIT 1 over them would return a different item on different days.
  SELECT * INTO v_asset FROM public.assets
   WHERE account_id = v_account
     AND upper(regexp_replace(coalesce(nfc_tag_uid,''), '[^A-Fa-f0-9]', '', 'g'))
       = upper(regexp_replace(v_v, '[^A-Fa-f0-9]', '', 'g'))
     AND coalesce(nfc_tag_uid,'') <> ''
   ORDER BY updated_at DESC, id LIMIT 1;
  IF FOUND THEN RETURN json_build_object('by','nfc_tag_uid','asset',row_to_json(v_asset)); END IF;

  RETURN NULL;
END;
$$;


--
-- Name: fp_inspection_tag_url(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_inspection_tag_url() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.tag_url IS NOT NULL AND NEW.tag_url <> '' THEN
    UPDATE public.assets
       SET tag_url = NEW.tag_url, updated_at = clock_timestamp()
     WHERE id = NEW.asset_id AND coalesce(tag_url, '') <> NEW.tag_url;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fp_pending_bsi(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_pending_bsi(p_work_order text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.my_account_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN (
    SELECT coalesce(json_agg(x ORDER BY x.work_order_id, x.serial_num), '[]'::json)
    FROM (
      SELECT i.id AS inspection_id, i.work_order_id,
             a.serial_raw AS serial_num, i.item_type, i.manufacturer, i.model,
             i.inspection_date, i.overall_pass, i.discard_reason
        FROM public.fp_inspections i
        JOIN public.assets a ON a.id = i.asset_id
       WHERE i.account_id = v_account
         AND i.is_current AND NOT i.is_deleted
         AND i.bsi_pushed_at IS NULL
         AND i.work_order_id IS NOT NULL
         AND (p_work_order IS NULL OR i.work_order_id = p_work_order)
    ) x);
END;
$$;


--
-- Name: fp_publish_template(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_publish_template(p_model_id uuid, p_type_id uuid, p_checks jsonb) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_version integer;
  v_tpl     uuid;
  v_chk     jsonb;
  v_ord     integer := 0;
  v_count   integer := 0;
  v_style   text;
BEGIN
  SELECT coalesce(max(version), 0) + 1 INTO v_version
    FROM public.fp_check_templates
   WHERE model_id IS NOT DISTINCT FROM p_model_id
     AND equipment_type_id IS NOT DISTINCT FROM p_type_id;

  INSERT INTO public.fp_check_templates (model_id, equipment_type_id, version, published_at, created_by)
  VALUES (p_model_id, p_type_id, v_version, now(), auth.uid())
  RETURNING id INTO v_tpl;

  FOR v_chk IN SELECT * FROM jsonb_array_elements(coalesce(p_checks, '[]'::jsonb)) LOOP
    CONTINUE WHEN nullif(trim(coalesce(v_chk->>'prompt','')), '') IS NULL;
    v_style := lower(coalesce(nullif(v_chk->>'answer_style',''), 'pass_fail'));
    IF v_style NOT IN ('pass_fail', 'yes_no') THEN
      RAISE EXCEPTION 'Unknown answer style "%" on check "%"', v_style, v_chk->>'prompt';
    END IF;
    INSERT INTO public.fp_template_checks
      (template_id, ord, code, prompt, answer_style, pass_answer, required)
    VALUES (
      v_tpl, v_ord,
      nullif(v_chk->>'code',''),
      trim(v_chk->>'prompt'),
      v_style,
      coalesce((v_chk->>'pass_answer')::boolean, true),
      coalesce((v_chk->>'required')::boolean, true));
    v_ord := v_ord + 1;
    v_count := v_count + 1;
  END LOOP;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'A published checklist needs at least one check';
  END IF;

  RETURN json_build_object('version', v_version, 'checks', v_count, 'template_id', v_tpl);
END;
$$;


--
-- Name: fp_record_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_record_detail(p_asset_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.my_account_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.assets
                  WHERE id = p_asset_id AND account_id = v_account) THEN
    RAISE EXCEPTION 'No such item';
  END IF;

  RETURN json_build_object(
    'asset', (SELECT row_to_json(a) FROM (
        SELECT id, serial_raw, serial_key, public_ref, nfc_tag_uid, tag_url, created_at
          FROM public.assets WHERE id = p_asset_id) a),
    -- Superseded and deleted rows are INCLUDED. The history of what a record
    -- used to say is part of the record; hiding it would defeat the point of
    -- never destroying one.
    'history', (SELECT coalesce(json_agg(h ORDER BY h.inspection_date DESC, h.version DESC), '[]'::json)
      FROM (
        SELECT i.id, i.inspection_date, i.next_due_date, i.item_type, i.manufacturer,
               i.model, i.lot_number, i.mfg_month, i.mfg_year, i.description,
               i.overall_pass, i.status, i.discard_reason, i.discard_note,
               i.collector_name, i.rep_number, i.work_order_id, i.source,
               i.version, i.is_current, i.is_deleted, i.supersedes,
               i.tag_url, i.created_at,
               (SELECT coalesce(json_agg(json_build_object(
                         'ord', c.ord, 'prompt', c.prompt, 'answer', c.answer,
                         'answer_style', c.answer_style, 'result', c.result)
                       ORDER BY c.ord), '[]'::json)
                  FROM public.fp_inspection_checks c WHERE c.fp_inspection_id = i.id) AS checks
          FROM public.fp_inspections i
         WHERE i.asset_id = p_asset_id
      ) h),
    'claims', (SELECT coalesce(json_agg(x ORDER BY x.created_at DESC), '[]'::json)
      FROM (SELECT source_url, fetched_at, claimed_inspection_date, claimed_pass,
                   claimed_result_text, claimed, created_at
              FROM public.fp_external_records WHERE asset_id = p_asset_id) x),
    'audit', (SELECT coalesce(json_agg(x ORDER BY x.created_at DESC), '[]'::json)
      FROM (SELECT action, reason, actor_name, created_at
              FROM public.fp_record_audit WHERE asset_id = p_asset_id) x)
  );
END;
$$;


--
-- Name: fp_records(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_records(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_q       text := nullif(btrim(coalesce(p_search, '')), '');
  v_key     text := public.serial_key(coalesce(p_search, ''));
  v_out     json;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT json_build_object(
    'total', (SELECT count(*) FROM public.assets a
               WHERE a.account_id = v_account AND a.kind = 'fall_protection'),
    'rows', coalesce(json_agg(r), '[]'::json)
  ) INTO v_out
  FROM (
    SELECT a.id AS asset_id, a.serial_raw, a.serial_key, a.public_ref,
           a.nfc_tag_uid, a.tag_url, a.tag_label,
           i.id AS inspection_id, i.inspection_date, i.next_due_date,
           i.item_type, i.manufacturer, i.model, i.lot_number,
           i.mfg_month, i.mfg_year, i.description,
           i.overall_pass, i.status, i.discard_reason,
           public.fp_effective_status(i.overall_pass, i.next_due_date, i.status) AS effective_status,
           i.collector_name, i.rep_number, i.work_order_id, i.source, i.version,
           (SELECT count(*) FROM public.fp_inspections h
             WHERE h.asset_id = a.id AND NOT h.is_deleted) AS history_count
      FROM public.assets a
      LEFT JOIN LATERAL (
        SELECT * FROM public.fp_inspections f
         WHERE f.asset_id = a.id AND f.is_current AND NOT f.is_deleted
         ORDER BY f.inspection_date DESC LIMIT 1
      ) i ON true
     WHERE a.account_id = v_account
       AND a.kind = 'fall_protection'
       AND (v_q IS NULL
            OR a.serial_key LIKE '%' || v_key || '%'
            -- The label the tech is reading off the tag in his hand.
            OR (a.tag_label_key <> '' AND a.tag_label_key LIKE '%' || v_key || '%')
            OR upper(coalesce(a.public_ref, '')) = upper(v_q)
            OR upper(coalesce(a.nfc_tag_uid, '')) LIKE '%' || upper(v_q) || '%'
            OR coalesce(i.manufacturer, '') ILIKE '%' || v_q || '%'
            OR coalesce(i.model, '') ILIKE '%' || v_q || '%'
            OR coalesce(i.item_type, '') ILIKE '%' || v_q || '%')
       AND (p_status IS NULL
            OR (p_status = 'due_soon'
                AND i.next_due_date IS NOT NULL
                AND i.next_due_date BETWEEN current_date AND current_date + 60)
            OR public.fp_effective_status(i.overall_pass, i.next_due_date, i.status) = p_status)
     ORDER BY coalesce(i.inspection_date, '1900-01-01') DESC, a.serial_key
     LIMIT greatest(1, least(coalesce(p_limit, 100), 500))
     OFFSET greatest(0, coalesce(p_offset, 0))
  ) r;

  RETURN v_out;
END;
$$;


--
-- Name: fp_seed_standard_types(); Type: FUNCTION; Schema: public; Owner: -
