  v_def  jsonb;
  v_id   uuid;
  v_n    integer := 0;
BEGIN
  FOR v_def IN SELECT * FROM jsonb_array_elements(v_defs) LOOP
    INSERT INTO public.fp_equipment_types (account_id, slug, name, sort_order)
    VALUES (NULL, v_def->>'slug', v_def->>'name', (v_def->>'sort_order')::integer)
    ON CONFLICT (coalesce(account_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(slug))
    DO UPDATE SET name = EXCLUDED.name, sort_order = EXCLUDED.sort_order
    RETURNING id INTO v_id;

    -- Only publish a baseline if this type has never had one.
    IF NOT EXISTS (SELECT 1 FROM public.fp_check_templates
                    WHERE equipment_type_id = v_id AND published_at IS NOT NULL) THEN
      PERFORM public.fp_publish_template(NULL, v_id, v_def->'checks');
      v_n := v_n + 1;
    END IF;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: fp_tag_url(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_tag_url(p_public_ref text, p_serial text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN nullif(btrim(coalesce(p_public_ref,'')),'') IS NULL THEN NULL ELSE
    (SELECT value FROM public.app_settings WHERE key = 'certificate_base_url')
    || '/fp/?t=' || p_public_ref
    || CASE WHEN nullif(btrim(coalesce(p_serial,'')),'') IS NULL THEN ''
            ELSE '&s=' || public.urlencode_serial(p_serial) END
  END;
$$;


--
-- Name: fp_tag_url_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_tag_url_key(p_url text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  s        text := btrim(coalesce(p_url, ''));
  scheme   text;
  rest     text;
  frag     text;
  query    text;
  hostport text;
  path     text;
  host     text;
  port     text;
  kept     text[] := '{}';
  kv       text;
BEGIN
  IF s = '' THEN RETURN ''; END IF;

  -- Not a URL at all. Still worth a stable key so a malformed link is at least
  -- consistent with itself, which is what the JS side does too.
  IF s !~ '^[A-Za-z][A-Za-z0-9+.-]*://' THEN RETURN lower(s); END IF;

  scheme := lower(substring(s from '^([A-Za-z][A-Za-z0-9+.-]*)://'));
  rest   := substring(s from '^[A-Za-z][A-Za-z0-9+.-]*://(.*)$');

  frag := substring(rest from '#(.*)$');
  rest := regexp_replace(rest, '#.*$', '');

  query := substring(rest from '\?(.*)$');
  rest  := regexp_replace(rest, '\?.*$', '');

  hostport := split_part(rest, '/', 1);
  path     := coalesce(substring(rest from '^[^/]*(/.*)$'), '');

  -- Credentials in the authority are stripped rather than keyed on: the same
  -- link with and without them is the same link.
  IF position('@' in hostport) > 0 THEN
    hostport := substring(hostport from '@(.*)$');
  END IF;

  host := lower(split_part(hostport, ':', 1));
  host := regexp_replace(host, '^www\.', '');
  port := nullif(split_part(hostport, ':', 2), '');

  IF port IS NOT NULL AND ((scheme = 'https' AND port = '443')
                        OR (scheme = 'http'  AND port = '80')) THEN
    port := NULL;
  END IF;

  path := regexp_replace(path, '/+$', '');

  IF query IS NOT NULL AND query <> '' THEN
    SELECT array_agg(p ORDER BY split_part(p, '=', 1))
      INTO kept
      FROM unnest(string_to_array(query, '&')) AS p
     WHERE p <> ''
       AND split_part(p, '=', 1) !~* '^(utm_|fbclid$|gclid$|mc_[ce]id$|_ga$|ref$|source$)';
  END IF;

  -- Only a sheet tab id survives in the fragment: for Google Sheets #gid=N is
  -- the sole thing distinguishing one tab from another, so dropping it would
  -- merge every tab of a workbook into one item.
  IF frag IS NULL OR frag !~ '^gid=[0-9]+$' THEN
    frag := NULL;
  END IF;

  RETURN scheme || '://' || host
      || coalesce(':' || port, '')
      || path
      || CASE WHEN kept IS NULL OR array_length(kept, 1) IS NULL
              THEN '' ELSE '?' || array_to_string(kept, '&') END
      || coalesce('#' || frag, '');
END;
$_$;


--
-- Name: fp_tag_write_plan(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_tag_write_plan(p jsonb) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_asset   public.assets%ROWTYPE;
  v_label   text := nullif(btrim(coalesce(p->>'tag_label','')), '');
  v_clash   uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO v_asset FROM public.assets
   WHERE account_id = v_account
     AND ( (nullif(p->>'asset_id','') IS NOT NULL AND id = (p->>'asset_id')::uuid)
        OR (nullif(p->>'serial_num','') IS NOT NULL
            AND kind = 'fall_protection' AND serial_key = public.serial_key(p->>'serial_num'))
        OR (nullif(p->>'public_ref','') IS NOT NULL AND public_ref = upper(p->>'public_ref')) )
   LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No such item — inspect it first, then write its tag';
  END IF;

  -- Caught here as well as by the unique index, so the tech is told BEFORE he
  -- holds a phone against a tag rather than after the write has half happened.
  IF v_label IS NOT NULL THEN
    SELECT id INTO v_clash FROM public.assets
     WHERE account_id = v_account AND tag_label_key = public.serial_key(v_label)
       AND id <> v_asset.id;
    IF FOUND THEN
      RAISE EXCEPTION 'Tag label % is already on another item', v_label;
    END IF;
  END IF;

  RETURN json_build_object(
    'asset_id',   v_asset.id,
    'has_tag',    (v_asset.tag_label IS NOT NULL OR v_asset.nfc_tag_uid IS NOT NULL),
    'serial_num', v_asset.serial_raw,
    'public_ref', v_asset.public_ref,
    'tag_label',  coalesce(v_label, v_asset.tag_label),
    'url',        public.fp_tag_url(v_asset.public_ref, v_asset.serial_raw),
    'prev_label', v_asset.tag_label,
    'prev_uid',   v_asset.nfc_tag_uid);
END;
$$;


--
-- Name: fp_type_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_type_catalog() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid;
  v_out     jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  -- Follows the account being acted as; identical when not impersonating.
  v_account := public.my_account_id();

  -- Ordered NUMERICALLY: t->>'sort_order' is text, so 10 would sort before 2.
  SELECT coalesce(jsonb_agg(t ORDER BY (t->>'sort_order')::integer, t->>'name'), '[]'::jsonb)
    INTO v_out
    FROM (
      SELECT jsonb_build_object(
               'id',         et.id,
               'slug',       et.slug,
               'name',       et.name,
               'sort_order', et.sort_order,
               'template_id',      tpl.template_id,
               'template_version', tpl.version,
               'checks', coalesce(tpl.checks, '[]'::jsonb)
             ) AS t
        FROM public.fp_equipment_types et
        LEFT JOIN LATERAL (
          SELECT c.template_id, c.version,
                 jsonb_agg(jsonb_build_object(
                   'ord', c.ord, 'code', c.code, 'prompt', c.prompt,
                   'answer_style', c.answer_style, 'pass_answer', c.pass_answer,
                   'required', c.required) ORDER BY c.ord) AS checks
            FROM public.fp_current_checks(NULL, et.id) c
           GROUP BY c.template_id, c.version
        ) tpl ON true
       WHERE et.is_active
         AND (et.account_id = v_account OR et.account_id IS NULL)
         -- An account's own type shadows the shared one of the same slug.
         AND NOT (et.account_id IS NULL AND EXISTS (
               SELECT 1 FROM public.fp_equipment_types own
                WHERE own.account_id = v_account AND own.is_active
                  AND lower(own.slug) = lower(et.slug)))
    ) s;

  RETURN v_out;
END;
$$;


--
-- Name: fp_type_for(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_type_for(p_account uuid, p_key text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT id FROM public.fp_equipment_types
   WHERE is_active
     AND (account_id = p_account OR account_id IS NULL)
     AND (lower(slug) = lower(trim(coalesce(p_key, '')))
          OR lower(name) = lower(trim(coalesce(p_key, ''))))
   ORDER BY (account_id IS NULL)     -- false (own) sorts before true (shared)
   LIMIT 1;
$$;


--
-- Name: gen_public_ref(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_public_ref() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  alphabet constant text := '0123456789BCDFGHJKLMNPQRSTVWXZ';
  out text := '';
BEGIN
  FOR i IN 1..10 LOOP
    out := out || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  END LOOP;
  RETURN out;
END;
$$;


--
-- Name: gen_ticket_ref(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_ticket_ref() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  alphabet text := '23456789BCDFGHJKLMNPQRSTVWXYZ';
  out text := '';
  i integer;
BEGIN
  FOR i IN 1..5 LOOP
    out := out || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  END LOOP;
  RETURN 'LIA-' || out;
END;
$$;


--
-- Name: get_my_credits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_credits() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_credits integer;
BEGIN
  SELECT a.credits INTO v_credits
  FROM public.accounts a
  JOIN public.account_members m ON m.account_id = a.id
  WHERE m.user_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'User record not found'; END IF;
  RETURN v_credits;
END;
$$;


--
-- Name: get_my_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_profile() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  SELECT u.id, u.email, u.name, a.plan, a.credits, u.created_at,
         a.id   AS account_id,
         a.name AS account_name,
         m.role, m.desktop_access
  INTO r
  FROM public.users u
  JOIN public.account_members m ON m.user_id = u.id
  JOIN public.accounts a        ON a.id = m.account_id
  WHERE u.id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'User record not found'; END IF;
  RETURN row_to_json(r);
END;
$$;


--
-- Name: ip_prefix(inet); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ip_prefix(p_ip inet) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_ip IS NULL THEN NULL
    WHEN family(p_ip) = 4 THEN host(network(set_masklen(p_ip, 24))) || '/24'
    ELSE host(network(set_masklen(p_ip, 48))) || '/48'
  END;
$$;


--
-- Name: is_developer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_developer() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce((SELECT is_developer FROM public.users WHERE id = auth.uid()), false);
$$;


--
-- Name: is_impersonating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_impersonating() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.active_impersonation());
$$;


--
-- Name: job_board(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_board(p_status text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.require_lead();
BEGIN
  RETURN (
    SELECT coalesce(json_agg(json_build_object(
             'id', j.id, 'wo_number', j.wo_number, 'scope', j.scope,
             'title', j.title, 'site', j.site, 'notes', j.notes,
             'due_date', j.due_date, 'status', j.status,
             'assign_all', j.assign_all, 'share_peer_work', j.share_peer_work,
             'closed_at', j.closed_at, 'close_note', j.close_note,
             'assignees', (
               SELECT coalesce(json_agg(json_build_object(
                        'user_id', u.id, 'name', u.name) ORDER BY u.name), '[]'::json)
                 FROM public.job_assignees ja JOIN public.users u ON u.id = ja.user_id
                WHERE ja.job_id = j.id),
             'progress', (
               SELECT coalesce(json_agg(json_build_object(
                        'user_id', pr.user_id, 'who', pr.who, 'n', pr.n, 'last_at', pr.last_at)), '[]'::json)
                 FROM public.job_progress(v_account, j.wo_key, j.scope) pr),
             'total', (
               SELECT coalesce(sum(pr.n), 0)::int
                 FROM public.job_progress(v_account, j.wo_key, j.scope) pr),
             'updated_at', j.updated_at
           ) ORDER BY (j.status <> 'open'), j.due_date NULLS LAST, j.updated_at DESC), '[]'::json)
      FROM public.jobs j
     WHERE j.account_id = v_account
       AND (p_status IS NULL OR j.status = p_status)
  );
END;
$$;


--
-- Name: job_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_detail(p_job_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_uid     uuid := auth.uid();
  v_lead    boolean;
  v_job     public.jobs%ROWTYPE;
  v_share   boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id AND account_id = v_account;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such job'; END IF;

  SELECT (role = 'lead') INTO v_lead FROM public.account_members WHERE user_id = v_uid;
  -- A lead always sees everything; a tech sees peers' work only if told to.
  v_share := coalesce(v_lead, false) OR v_job.share_peer_work;

  RETURN json_build_object(
    'job', row_to_json(v_job),
    'assignees', (
      SELECT coalesce(json_agg(json_build_object(
               'user_id', u.id, 'name', u.name, 'email', u.email) ORDER BY u.name), '[]'::json)
        FROM public.job_assignees ja JOIN public.users u ON u.id = ja.user_id
       WHERE ja.job_id = v_job.id),
    'progress', (
      SELECT coalesce(json_agg(json_build_object(
               'user_id', pr.user_id, 'who', pr.who, 'n', pr.n, 'last_at', pr.last_at)), '[]'::json)
        FROM public.job_progress(v_account, v_job.wo_key, v_job.scope) pr),
    'share_peer_work', v_job.share_peer_work,
    'can_see_peers', v_share,
    -- The records themselves. A tech with sharing off gets ONLY his own rows
    -- back from the server; the filtering is not left to the client.
    'records', (
      SELECT coalesce(json_agg(r ORDER BY r->>'at' DESC), '[]'::json) FROM (
        SELECT json_build_object(
                 'id', i.id, 'serial', a.serial_raw, 'kind', 'fall_protection',
                 'date', i.inspection_date, 'pass', i.overall_pass,
                 'item_type', i.item_type, 'who', i.collector_name,
                 'mine', (i.collected_by IS NOT DISTINCT FROM v_uid),
                 'at', i.uploaded_at) AS r
          FROM public.fp_inspections i JOIN public.assets a ON a.id = i.asset_id
         WHERE v_job.scope = 'fall_protection'
           AND i.account_id = v_account AND i.is_current AND NOT i.is_deleted
           AND public.wo_key(i.work_order_id) = v_job.wo_key
           AND (v_share OR i.collected_by IS NOT DISTINCT FROM v_uid)
        UNION ALL
        SELECT json_build_object(
                 'id', i.id, 'serial', i.serial_num, 'kind', 'ladder',
                 'date', i.inspection_date, 'pass', true,
                 'item_type', i.type, 'who', i.tech_name,
                 'mine', (i.tech_user_id IS NOT DISTINCT FROM v_uid),
                 'at', i.created_at)
          FROM public.inspections i
         WHERE v_job.scope = 'ladder'
           AND i.account_id = v_account
           AND public.wo_key(i.work_order_id) = v_job.wo_key
           AND (v_share OR i.tech_user_id IS NOT DISTINCT FROM v_uid)
      ) s)
  );
END;
$$;


--
-- Name: job_progress(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_progress(p_account uuid, p_wo_key text, p_scope text) RETURNS TABLE(user_id uuid, who text, n integer, last_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM (
    SELECT i.collected_by AS user_id,
           coalesce(nullif(i.collector_name, ''), 'Unattributed') AS who,
           count(*)::int AS n,
           max(i.uploaded_at) AS last_at
      FROM public.fp_inspections i
     WHERE p_scope = 'fall_protection'
       AND i.account_id = p_account
       AND i.is_current AND NOT i.is_deleted
       AND public.wo_key(i.work_order_id) = p_wo_key
     GROUP BY 1, 2
    UNION ALL
    SELECT i.tech_user_id,
           coalesce(nullif(i.tech_name, ''), 'Unattributed'),
           count(*)::int,
           max(i.created_at)
      FROM public.inspections i
     WHERE p_scope = 'ladder'
       AND i.account_id = p_account
       AND public.wo_key(i.work_order_id) = p_wo_key
     GROUP BY 1, 2
  ) t ORDER BY n DESC, who;
$$;


--
-- Name: mark_bsi_pushed(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bsi_pushed(p jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.my_account_id(); v_n integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  UPDATE public.inspections i
     SET bsi_pushed_at = now(),
         bsi_box_ref   = coalesce(e->>'box_ref', i.bsi_box_ref),
         updated_at    = now()
    FROM jsonb_array_elements(coalesce(p->'items','[]'::jsonb)) e
   WHERE i.id = (e->>'inspection_id')::uuid
     AND i.account_id = v_account
     AND i.is_current AND NOT i.is_deleted;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: mark_fp_bsi_pushed(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_fp_bsi_pushed(p jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_n       integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  WITH upd AS (
    UPDATE public.fp_inspections i
       SET bsi_pushed_at = now(),
           bsi_box_ref = coalesce(e->>'box_ref', i.bsi_box_ref),
           updated_at = now()
      FROM jsonb_array_elements(coalesce(p->'items', '[]'::jsonb)) e
     WHERE i.id = (e->>'inspection_id')::uuid
       AND i.account_id = v_account
    RETURNING 1)
  SELECT count(*) INTO v_n FROM upd;
  RETURN v_n;
END;
$$;


--
-- Name: mark_support_ticket_read(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_support_ticket_read(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid := nullif(p->>'ticket_id','')::uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF public.is_developer() THEN
    UPDATE public.support_tickets SET unread_developer = false WHERE id = v_id;
  ELSE
    UPDATE public.support_tickets SET unread_reporter = false
     WHERE id = v_id AND created_by = auth.uid();
  END IF;
END;
$$;


--
-- Name: my_account_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_account_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT s.account_id FROM public.active_impersonation() s),
    (SELECT account_id FROM public.account_members
      WHERE user_id = auth.uid() AND removed_at IS NULL)
  );
$$;


--
-- Name: my_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_context() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'account_id',      public.my_account_id(),
    'account_name',    (SELECT name FROM public.accounts WHERE id = public.my_account_id()),
    'real_account_id', public.my_real_account_id(),
    'real_account_name', (SELECT name FROM public.accounts WHERE id = public.my_real_account_id()),
    'impersonating',   public.is_impersonating(),
    'expires_at',      (SELECT expires_at FROM public.active_impersonation()),
    'reason',          (SELECT reason FROM public.active_impersonation()),
    'role',            (SELECT role FROM public.account_members
                         WHERE user_id = auth.uid() AND removed_at IS NULL),
    'is_umbrella',     (SELECT a.parent_account_id IS NULL
                          FROM public.accounts a WHERE a.id = public.my_real_account_id()),
    -- Does the account being worked in have subcontractors of its own?
    'acting_is_umbrella', EXISTS (SELECT 1 FROM public.accounts
                                   WHERE parent_account_id = public.my_account_id()),
    'can_act_as',      coalesce((
       SELECT json_agg(json_build_object('account_id', a.id, 'name', a.name) ORDER BY a.name)
         FROM public.accounts a
         JOIN public.account_descendants(public.my_real_account_id()) d ON d.account_id = a.id
        WHERE a.id <> public.my_real_account_id()
          AND EXISTS (SELECT 1 FROM public.account_members m
                       WHERE m.user_id = auth.uid() AND m.role = 'lead'
                         AND m.removed_at IS NULL)
     ), '[]'::json)
  );
$$;


--
-- Name: my_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_jobs(p_closed_days integer DEFAULT 2) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_uid     uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN (
    SELECT coalesce(json_agg(json_build_object(
             'id', j.id,
             'wo_number', j.wo_number,
             'wo_key', j.wo_key,
             'scope', j.scope,
             'title', j.title,
             'site', j.site,
             'notes', j.notes,
             'due_date', j.due_date,
             'status', j.status,
             'share_peer_work', j.share_peer_work,
             'assigned_to_me', EXISTS (
               SELECT 1 FROM public.job_assignees ja
                WHERE ja.job_id = j.id AND ja.user_id = v_uid),
             'team_wide', j.assign_all,
             'mine_count', (
               SELECT coalesce(sum(pr.n), 0)::int FROM public.job_progress(v_account, j.wo_key, j.scope) pr
                WHERE pr.user_id IS NOT DISTINCT FROM v_uid),
             -- Only meaningful when sharing is on, and zero rather than a lie
             -- when it is off.
             'team_count', CASE WHEN j.share_peer_work THEN (
               SELECT coalesce(sum(pr.n), 0)::int FROM public.job_progress(v_account, j.wo_key, j.scope) pr)
               ELSE 0 END,
             -- Who planned this. On a shared phone, and on any phone whose
             -- tech works for more than one lead, "who told me to do this"
             -- is the first question and there was no answer on the device.
             'assigned_by', (
               SELECT coalesce(u.name, u.email) FROM public.users u WHERE u.id = j.created_by),
             'assigned_by_email', (
               SELECT u.email FROM public.users u WHERE u.id = j.created_by),
             'updated_at', j.updated_at
           ) ORDER BY j.status, j.due_date NULLS LAST, j.updated_at DESC), '[]'::json)
      FROM public.jobs j
     WHERE j.account_id = v_account
       AND (j.assign_all OR EXISTS (
             SELECT 1 FROM public.job_assignees ja
              WHERE ja.job_id = j.id AND ja.user_id = v_uid))
       AND (j.status = 'open'
            OR (j.status <> 'open' AND j.closed_at > now() - make_interval(days => greatest(0, coalesce(p_closed_days, 2)))))
  );
END;
$$;


--
-- Name: my_network(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_network() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ip inet := public.request_ip();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN json_build_object(
    'ip', host(v_ip),
    'prefix', public.ip_prefix(v_ip),
    'suggested_cidr', CASE WHEN v_ip IS NULL THEN NULL
                           WHEN family(v_ip) = 4 THEN host(network(set_masklen(v_ip, 24))) || '/24'
                           ELSE host(network(set_masklen(v_ip, 48))) || '/48' END);
END;
$$;


--
-- Name: my_real_account_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_real_account_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT account_id FROM public.account_members
   WHERE user_id = auth.uid() AND removed_at IS NULL;
$$;


--
-- Name: my_subcontractors(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_subcontractors() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_real uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  v_real := public.my_real_account_id();

  RETURN (
    SELECT coalesce(json_agg(json_build_object(
             'account_id', a.id,
             'name',       a.name,
             'credits',    a.credits,
             'lead',       l.name,
             'lead_email', l.email,
             'rep_number', l.rep_number,
             'members',    (SELECT count(*) FROM public.account_members m WHERE m.account_id = a.id),
             'records',    (SELECT count(*) FROM public.inspections i WHERE i.account_id = a.id)
                         + (SELECT count(*) FROM public.fp_inspections f WHERE f.account_id = a.id),
             'last_at',    (SELECT max(i.created_at) FROM public.inspections i WHERE i.account_id = a.id)
           ) ORDER BY a.name), '[]'::json)
      FROM public.accounts a
      LEFT JOIN LATERAL (
        SELECT u.name, u.email, m.rep_number
          FROM public.account_members m JOIN public.users u ON u.id = m.user_id
         WHERE m.account_id = a.id AND m.role = 'lead'
         ORDER BY m.rep_number NULLS LAST LIMIT 1
      ) l ON true
     WHERE a.parent_account_id = v_real);
END;
$$;


--
-- Name: my_support_tickets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_support_tickets() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(json_agg(t ORDER BY t.last_message_at DESC), '[]'::json)
  FROM (
    SELECT s.id, s.ref, s.client_id, s.kind, s.severity, s.subject, s.status,
           s.created_at, s.last_message_at, s.unread_reporter,
           (SELECT coalesce(json_agg(json_build_object(
                     'id', m.id, 'author_role', m.author_role,
                     'author_name', m.author_name, 'body', m.body,
                     'created_at', m.created_at) ORDER BY m.created_at), '[]'::json)
              FROM public.support_messages m WHERE m.ticket_id = s.id) AS messages
      FROM public.support_tickets s
     WHERE s.created_by = auth.uid()
  ) t;
$$;


--
-- Name: preflight_work_order(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preflight_work_order(p_wo_number text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id    uuid := auth.uid();
  v_account_id uuid;
  v_credits    integer;
  v_key        text;
  v_charged    boolean := false;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_key := public.wo_key(p_wo_number);
  IF v_key = '' THEN RAISE EXCEPTION 'A work order number is required'; END IF;

  -- Follows the account being acted as; identical when not impersonating.
  v_account_id := public.my_account_id();
  IF v_account_id IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  SELECT credits INTO v_credits FROM public.accounts WHERE id = v_account_id;

  SELECT (charged_at IS NOT NULL) INTO v_charged
  FROM public.work_orders WHERE account_id = v_account_id AND wo_key = v_key;

  RETURN json_build_object(
    'credits',         v_credits,
    'already_charged', COALESCE(v_charged, false),
    -- true when this import will not cost anything: already paid, or unlimited
    'free',            COALESCE(v_charged, false) OR v_credits = -1,
    'can_run',         COALESCE(v_charged, false) OR v_credits = -1 OR v_credits > 0
  );
END;
$$;


--
-- Name: publish_fp_checks(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_fp_checks(p_model_id uuid, p_checks jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.require_lead();
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.fp_models
                  WHERE id = p_model_id AND account_id = v_account) THEN
    RAISE EXCEPTION 'That model is not on your account';
  END IF;
  RETURN public.fp_publish_template(p_model_id, NULL, p_checks);
END;
$$;


--
-- Name: publish_fp_type_checks(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_fp_type_checks(p_type_id uuid, p_checks jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_src     public.fp_equipment_types%ROWTYPE;
  v_target  uuid;
BEGIN
  SELECT * INTO v_src FROM public.fp_equipment_types WHERE id = p_type_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such equipment type'; END IF;

  IF v_src.account_id = v_account THEN
    v_target := v_src.id;
  ELSIF v_src.account_id IS NULL THEN
    INSERT INTO public.fp_equipment_types (account_id, slug, name, sort_order, created_by)
    VALUES (v_account, v_src.slug, v_src.name, v_src.sort_order, auth.uid())
    ON CONFLICT (coalesce(account_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(slug))
    DO UPDATE SET name = EXCLUDED.name
    RETURNING id INTO v_target;
  ELSE
    RAISE EXCEPTION 'That equipment type is not on your account';
  END IF;

  RETURN public.fp_publish_template(NULL, v_target, p_checks);
END;
$$;


--
-- Name: record_certificate_view(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_certificate_view(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_source  text := coalesce(nullif(p->>'source',''), 'web');
  v_ua      text := left(coalesce(nullif(p->>'user_agent',''), ''), 400);
  v_ref     text := nullif(upper(btrim(coalesce(p->>'public_ref',''))), '');
  v_serial  text := nullif(p->>'serial_key','');
  v_kind    text := nullif(p->>'kind','');
  v_found   boolean := coalesce((p->>'found')::boolean, true);
  v_lookup  text := nullif(p->>'lookup_by','');
  v_ip      inet;
  v_prefix  text;
  v_net     public.known_networks%ROWTYPE;
  v_asset   public.assets%ROWTYPE;
  v_class   text;
  v_viewer  text := 'unknown';
  v_label   text;
  v_bucket  timestamptz := date_trunc('hour', now());
BEGIN
  -- Views from our own apps are not visits. A tech opening a certificate from
  -- inside Lia Field, or the office app rendering one, would otherwise swamp
  -- the only signal this table exists to capture: whether anybody OUTSIDE is
  -- using the tags.
  IF v_source <> 'web' THEN RETURN; END IF;
  -- Belt and braces, in case an app forgets to say so. Capacitor and Electron
  -- both put themselves in the user agent.
  IF v_ua ~* '(capacitor|lia-?field|lia-?office|electron)' THEN RETURN; END IF;

  v_class := public.device_class(v_ua);
  -- A crawler fetching a public URL is not a person looking at a certificate.
  IF v_class = 'bot' THEN RETURN; END IF;

  IF v_ref IS NULL AND v_serial IS NULL THEN RETURN; END IF;

  v_ip := public.request_ip();
  v_prefix := public.ip_prefix(v_ip);

  IF v_ip IS NOT NULL THEN
    SELECT * INTO v_net FROM public.known_networks
     -- <<= not <<. The strict operator excludes the network address itself, so
     -- labelling one machine as 198.51.100.9/32 would never match 198.51.100.9
     -- — the single most obvious thing anyone would try.
     WHERE v_ip <<= cidr
     -- The most specific matching network wins, so a single machine can be
     -- labelled inside a broader office range.
     ORDER BY masklen(cidr) DESC
     LIMIT 1;
    IF FOUND THEN
      v_viewer := v_net.kind;
      v_label  := v_net.label;
    END IF;
  END IF;

  -- No named network. A phone is more likely a tech in front of the item than
  -- somebody at a desk — a hint, and reported as such rather than as fact.
  IF v_viewer = 'unknown' AND v_class IN ('mobile', 'tablet') THEN
    v_viewer := 'field';
  END IF;

  -- Tie it to the item so a report can say which items get looked at. Resolved
  -- here rather than trusted from the client, which is a public page.
  IF v_ref IS NOT NULL THEN
    SELECT * INTO v_asset FROM public.assets WHERE public_ref = v_ref;
  END IF;
  IF v_asset.id IS NULL AND v_serial IS NOT NULL THEN
    SELECT * INTO v_asset FROM public.assets
     WHERE serial_key = public.serial_key(v_serial)
     ORDER BY created_at LIMIT 1;
  END IF;

  INSERT INTO public.certificate_views (
    kind, public_ref, serial_key, asset_id, account_id, found, lookup_by,
    viewer_kind, network_label, ip_prefix, device_class, user_agent, referrer, tz,
    bucket_hour
  ) VALUES (
    coalesce(v_kind, v_asset.kind), v_ref,
    CASE WHEN v_serial IS NULL THEN NULL ELSE public.serial_key(v_serial) END,
    v_asset.id, v_asset.account_id, v_found,
    v_lookup, v_viewer, v_label, v_prefix, v_class, v_ua,
    left(nullif(p->>'referrer',''), 300), left(nullif(p->>'tz',''), 60),
    v_bucket
  )
  ON CONFLICT (coalesce(public_ref, ''), coalesce(serial_key, ''),
               coalesce(ip_prefix, ''), bucket_hour)
  DO UPDATE SET
    hits = public.certificate_views.hits + 1,
    last_seen_at = now();
END;
$$;


--
-- Name: record_fp_external(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_fp_external(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_account uuid;
  v_url     text := nullif(btrim(coalesce(p->>'source_url', p->>'tag_url', '')), '');
  v_claim   jsonb := coalesce(p->'claimed', '{}'::jsonb);
  v_serial  text := nullif(btrim(coalesce(p->>'serial_num','')), '');
  v_asset   uuid;
  v_id      uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_url IS NULL THEN RAISE EXCEPTION 'An external record must say where it came from'; END IF;

  SELECT account_id INTO v_account FROM public.account_members WHERE user_id = v_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  IF v_serial IS NOT NULL THEN
    SELECT id INTO v_asset FROM public.assets
     WHERE account_id = v_account AND kind = 'fall_protection'
       AND serial_key = public.serial_key(v_serial);
  END IF;

  INSERT INTO public.fp_external_records (
    account_id, asset_id, source_url, fetched_at,
    claimed_serial, claimed_tag_id, claimed_inspection_date, claimed_next_due_date,
    claimed_pass, claimed_result_text, claimed_manufacturer, claimed_model,
    claimed_item_type, claimed_inspector, claimed, captured_at, created_by
  ) VALUES (
    v_account, v_asset, v_url, (p->>'fetched_at')::timestamptz,
    nullif(v_claim->>'serial',''),
    nullif(v_claim->>'tag_id',''),
    -- The client has already normalized these to ISO; anything it could not
    -- parse arrives null and the raw string stays in `claimed`.
    (nullif(v_claim->>'inspection_date',''))::date,
    (nullif(v_claim->>'next_due_date',''))::date,
    (v_claim->>'overall_pass')::boolean,
    nullif(v_claim->>'result_text',''),
    nullif(v_claim->>'manufacturer',''),
    nullif(v_claim->>'model',''),
    nullif(v_claim->>'item_type',''),
    nullif(v_claim->>'inspector',''),
    v_claim,
    (p->>'captured_at')::timestamptz,
    v_user
  )
  ON CONFLICT (account_id, source_url_key,
               coalesce(claimed_inspection_date, 'epoch'::date))
  DO UPDATE SET
    claimed    = EXCLUDED.claimed,
    asset_id   = coalesce(public.fp_external_records.asset_id, EXCLUDED.asset_id),
    fetched_at = coalesce(EXCLUDED.fetched_at, public.fp_external_records.fetched_at)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: record_fp_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_fp_inspection(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_account  uuid;
  v_serial   text := trim(coalesce(p->>'serial_num', ''));
  v_date     date := coalesce((p->>'inspection_date')::date, current_date);
  v_mfr      text := nullif(trim(coalesce(p->>'manufacturer','')), '');
  v_model    text := nullif(trim(coalesce(p->>'model','')), '');
  v_asset    uuid;
  v_model_id uuid;
  v_type_id  uuid;
  v_type_nm  text;
  v_prev     public.fp_inspections%ROWTYPE;
  v_id       uuid;
  v_version  integer := 1;
  v_rep      text;
  v_who      text;
  v_checks   jsonb := coalesce(p->'checks', '[]'::jsonb);
  v_chk      jsonb;
  v_pass     boolean := true;
  v_failed   text[] := '{}';
  v_reason   text;
  v_note     text := nullif(trim(coalesce(p->>'discard_note','')), '');
  v_ord      integer := 0;
  v_tpl      uuid;
  v_tplver   integer;
  v_code     text;
  v_prompt   text;
  v_style    text;
  v_passans  boolean;
  v_answer   boolean;
  v_result   boolean;
  v_source   text;
  v_seen     text[] := '{}';
  v_missing  text[];
  -- Checks are scored BEFORE the parent row exists, so they accumulate here
  -- rather than being inserted with a null parent and back-filled.
  v_scored   jsonb := '[]'::jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_serial = '' THEN RAISE EXCEPTION 'A serial number is required'; END IF;

  -- Follows the account being acted as; identical when not impersonating.
  v_account := public.my_account_id();
  IF v_account IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  v_rep := public.account_rep_number(v_account);
  SELECT coalesce(nullif(p->>'tech_name',''), u.name, u.email)
    INTO v_who FROM public.users u WHERE u.id = v_user_id;
  v_who := coalesce(v_who, 'Lia Import');

  -- Equipment type: an explicit id wins, else resolve the slug or name.
  v_type_id := nullif(p->>'equipment_type_id','')::uuid;
  IF v_type_id IS NULL THEN
    v_type_id := public.fp_type_for(v_account, coalesce(nullif(p->>'equipment_type',''),
                                                        nullif(p->>'item_type','')));
  END IF;
  SELECT name INTO v_type_nm FROM public.fp_equipment_types WHERE id = v_type_id;

  -- Catalogue entry, created on first sight of a manufacturer+model.
  IF v_mfr IS NOT NULL AND v_model IS NOT NULL THEN
    INSERT INTO public.fp_models (account_id, manufacturer, model, item_type,
                                  has_impact_indicator, created_by)
    VALUES (v_account, v_mfr, v_model,
            coalesce(v_type_nm, nullif(p->>'item_type','')),
            coalesce((p->>'has_impact_indicator')::boolean, false), v_user_id)
    ON CONFLICT (coalesce(account_id, '00000000-0000-0000-0000-000000000000'::uuid),
                 lower(manufacturer), lower(model))
    DO NOTHING;

    SELECT id INTO v_model_id FROM public.fp_models
     WHERE account_id IS NOT DISTINCT FROM v_account
       AND lower(manufacturer) = lower(v_mfr) AND lower(model) = lower(v_model);
  END IF;

  -- The template the CLIENT performed against, not necessarily today's. A tech
  -- works offline for a day; the checklist may have been republished since.
  -- Validating against the pinned version is what makes that record still valid.
  v_tpl := nullif(p->>'template_id','')::uuid;
  IF v_tpl IS NULL THEN
    v_tpl := public.fp_current_template(v_model_id, v_type_id);
  END IF;
  SELECT version INTO v_tplver FROM public.fp_check_templates WHERE id = v_tpl;

  -- ── Score the checks ──────────────────────────────────────────────────────
  FOR v_chk IN SELECT * FROM jsonb_array_elements(v_checks) LOOP
    v_code := nullif(v_chk->>'code','');

    -- Template values are authoritative where the check is in the template.
    v_prompt := NULL;
    IF v_tpl IS NOT NULL AND v_code IS NOT NULL THEN
      SELECT c.prompt, c.answer_style, c.pass_answer
        INTO v_prompt, v_style, v_passans
        FROM public.fp_template_checks c
       WHERE c.template_id = v_tpl AND c.code = v_code
       LIMIT 1;
    END IF;

    IF v_prompt IS NOT NULL THEN
      v_source := 'template';
      v_seen := v_seen || v_code;
    ELSE
      v_source  := 'adhoc';
      v_prompt  := coalesce(nullif(v_chk->>'prompt',''), '(no prompt recorded)');
      v_style   := lower(coalesce(nullif(v_chk->>'answer_style',''), 'pass_fail'));
      v_passans := coalesce((v_chk->>'pass_answer')::boolean, true);
      IF v_style NOT IN ('pass_fail', 'yes_no') THEN v_style := 'pass_fail'; END IF;
    END IF;

    -- The tech answers; the verdict is derived. A client cannot send an answer
    -- and a contradicting result.
    IF (v_chk ? 'answer') AND (v_chk->>'answer') IS NOT NULL THEN
      v_answer := (v_chk->>'answer')::boolean;
    ELSIF (v_chk->>'result') IS NOT NULL THEN
      -- Older clients send only a pass/fail verdict; back-fill the answer.
      v_answer := CASE WHEN (v_chk->>'result')::boolean THEN v_passans ELSE NOT v_passans END;
    ELSE
      v_answer := NULL;
    END IF;

    v_result := CASE WHEN v_answer IS NULL THEN NULL ELSE (v_answer = v_passans) END;

    IF v_result IS FALSE THEN
      v_pass := false;
      v_failed := v_failed || v_prompt;
    END IF;

    v_scored := v_scored || jsonb_build_object(
      'ord',          coalesce((v_chk->>'ord')::integer, v_ord),
      'code',         v_code,
      'prompt',       v_prompt,
      'answer',       v_answer,
      'answer_style', v_style,
      'pass_answer',  v_passans,
      'result',       v_result,
      'source',       v_source,
      'note',         nullif(v_chk->>'note',''));
    v_ord := v_ord + 1;
  END LOOP;

  -- "All must pass" only means something if all were actually asked.
  IF v_tpl IS NOT NULL THEN
    SELECT array_agg(c.prompt) INTO v_missing
      FROM public.fp_template_checks c
     WHERE c.template_id = v_tpl AND c.required
       AND NOT (c.code = ANY (v_seen));
    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION 'Unanswered required check(s): %', array_to_string(v_missing, '; ');
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_checks) e
              WHERE NOT (e ? 'answer') AND (e->>'result') IS NULL) THEN
    RAISE EXCEPTION 'Every check must be answered before an item can be recorded';
  END IF;

  -- The reason IS the failed checks. Nothing for the tech to type.
  IF NOT v_pass THEN
    v_reason := 'Failed: ' || array_to_string(v_failed, '; ');
  END IF;

  INSERT INTO public.assets (account_id, kind, serial_raw, serial_key)
  VALUES (v_account, 'fall_protection', v_serial, public.serial_key(v_serial))
  ON CONFLICT (account_id, kind, serial_key) DO NOTHING
  RETURNING id INTO v_asset;

  IF v_asset IS NULL THEN
    SELECT id INTO v_asset FROM public.assets
     WHERE account_id = v_account AND kind = 'fall_protection'
       AND serial_key = public.serial_key(v_serial);
  END IF;

  IF nullif(p->>'nfc_tag_serial','') IS NOT NULL THEN
    UPDATE public.assets SET nfc_tag_uid = p->>'nfc_tag_serial' WHERE id = v_asset;
  END IF;

  SELECT * INTO v_prev FROM public.fp_inspections
   WHERE asset_id = v_asset AND inspection_date = v_date AND is_current AND NOT is_deleted
   FOR UPDATE;

  IF FOUND THEN
    v_version := v_prev.version + 1;
    UPDATE public.fp_inspections SET is_current = false, updated_at = now() WHERE id = v_prev.id;
  END IF;

  INSERT INTO public.fp_inspections (
    account_id, asset_id, work_order_id, inspection_date, next_due_date,
    rep_number, tech_user_id, collected_by, collector_name,
    model_id, equipment_type_id, item_type, description, manufacturer, model,
    lot_number, mfg_month, mfg_year, status, nfc_tag_serial, tag_url,
    template_id, template_version, overall_pass, discard_reason, discard_note,
    version, supersedes, is_current, source, captured_at
  ) VALUES (
    v_account, v_asset,
    coalesce(nullif(p->>'work_order_id',''), v_prev.work_order_id),
    v_date,
    coalesce((p->>'next_due_date')::date, v_date + interval '1 year'),
    v_rep, v_user_id, v_user_id, v_who,
    coalesce(v_model_id, v_prev.model_id),
    coalesce(v_type_id, v_prev.equipment_type_id),
    coalesce(v_type_nm, nullif(p->>'item_type',''), v_prev.item_type),
    coalesce(nullif(p->>'description',''),  v_prev.description),
    coalesce(v_mfr,   v_prev.manufacturer),
    coalesce(v_model, v_prev.model),
    coalesce(nullif(p->>'lot_number',''),   v_prev.lot_number),
    coalesce((p->>'mfg_month')::integer,    v_prev.mfg_month),
    coalesce((p->>'mfg_year')::integer,     v_prev.mfg_year),
    public.fp_default_status(v_pass, nullif(p->>'status','')),
    coalesce(nullif(p->>'nfc_tag_serial',''), v_prev.nfc_tag_serial),
    -- Not carried over from the previous inspection: this column says which link
    -- the tech read THIS time. An item that has been re-tagged, or one tapped
    -- from a phone that read no link at all, must not inherit last year's.
    nullif(p->>'tag_url',''),
    coalesce(v_tpl, v_prev.template_id),
    coalesce(v_tplver, v_prev.template_version),
    v_pass, v_reason, coalesce(v_note, v_prev.discard_note),
    v_version, v_prev.id, true,
    coalesce(p->>'source', 'field'),
    coalesce((p->>'captured_at')::timestamptz, now())
  )
  RETURNING id INTO v_id;

  INSERT INTO public.fp_inspection_checks
    (fp_inspection_id, ord, code, prompt, answer, answer_style, pass_answer, result, source, note)
  SELECT v_id,
         (e->>'ord')::integer,
         nullif(e->>'code',''),
         e->>'prompt',
         (e->>'answer')::boolean,
         e->>'answer_style',
         (e->>'pass_answer')::boolean,
         (e->>'result')::boolean,
         e->>'source',
         nullif(e->>'note','')
    FROM jsonb_array_elements(v_scored) e;

  RETURN v_id;
END;
$$;


--
-- Name: record_fp_tag_link(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_fp_tag_link(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_account uuid;
  v_url     text := nullif(btrim(coalesce(p->>'tag_url','')), '');
  v_serial  text := nullif(btrim(coalesce(p->>'serial_num','')), '');
  v_asset   uuid;
  v_id      uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_url IS NULL THEN RAISE EXCEPTION 'A tag link is required'; END IF;

  SELECT account_id INTO v_account FROM public.account_members WHERE user_id = v_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  -- Tie it to an item where the tag named one. A sighting whose serial matches
  -- nothing stays unattached rather than creating an asset: an item this
  -- company has never inspected should not appear in its catalogue because
  -- somebody walked past it with a phone.
  IF v_serial IS NOT NULL THEN
    SELECT id INTO v_asset FROM public.assets
     WHERE account_id = v_account AND kind = 'fall_protection'
       AND serial_key = public.serial_key(v_serial);
  END IF;

  IF v_asset IS NULL AND nullif(p->>'public_ref','') IS NOT NULL THEN
    SELECT id INTO v_asset FROM public.assets
     WHERE account_id = v_account AND public_ref = p->>'public_ref';
  END IF;

  INSERT INTO public.fp_tag_links (
    account_id, asset_id, tag_url, nfc_tag_uid, public_ref, serial_num,
    work_order_id, claimed, fetched_at, created_by
  ) VALUES (
    v_account, v_asset, v_url,
    nullif(p->>'nfc_tag_serial',''), nullif(p->>'public_ref',''), v_serial,
    nullif(p->>'work_order_id',''),
    p->'claimed', (p->>'fetched_at')::timestamptz, v_user
  )
  ON CONFLICT (account_id, tag_url_key) DO UPDATE SET
    last_seen_at  = now(),
    seen_count    = public.fp_tag_links.seen_count + 1,
    -- Only ever fills gaps. A later sighting that learned less must not erase
    -- what an earlier one established.
    asset_id      = coalesce(public.fp_tag_links.asset_id, EXCLUDED.asset_id),
    nfc_tag_uid   = coalesce(public.fp_tag_links.nfc_tag_uid, EXCLUDED.nfc_tag_uid),
    serial_num    = coalesce(public.fp_tag_links.serial_num, EXCLUDED.serial_num),
    public_ref    = coalesce(public.fp_tag_links.public_ref, EXCLUDED.public_ref),
    claimed       = coalesce(EXCLUDED.claimed, public.fp_tag_links.claimed),
    fetched_at    = coalesce(EXCLUDED.fetched_at, public.fp_tag_links.fetched_at)
  RETURNING id INTO v_id;

  -- Where the sighting did resolve to an item, the item learns its link.
  IF v_asset IS NOT NULL THEN
    UPDATE public.assets
       SET tag_url = v_url, updated_at = clock_timestamp()
     WHERE id = v_asset AND coalesce(tag_url, '') <> v_url;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: record_fp_tag_write(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_fp_tag_write(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_account uuid;
  v_asset   public.assets%ROWTYPE;
  v_label   text := nullif(btrim(coalesce(p->>'tag_label','')), '');
  v_uid     text := nullif(btrim(coalesce(p->>'nfc_tag_uid','')), '');
  v_url     text := nullif(btrim(coalesce(p->>'tag_url','')), '');
  v_client  text := nullif(p->>'client_id','');
  v_clash   uuid;
  v_id      uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  -- Follows the account being acted as; identical when not impersonating.
  v_account := public.my_account_id();
  IF v_account IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  SELECT * INTO v_asset FROM public.assets
   WHERE account_id = v_account
     AND ( (nullif(p->>'asset_id','') IS NOT NULL AND id = (p->>'asset_id')::uuid)
        OR (nullif(p->>'serial_num','') IS NOT NULL
            AND kind = 'fall_protection' AND serial_key = public.serial_key(p->>'serial_num'))
        OR (nullif(p->>'public_ref','') IS NOT NULL AND public_ref = upper(p->>'public_ref')) )
   LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such item'; END IF;

  -- A label already on a DIFFERENT item is refused rather than moved. Moving it
  -- would leave the other item unfindable by the label printed on its own tag.
  IF v_label IS NOT NULL THEN
    SELECT id INTO v_clash FROM public.assets
     WHERE account_id = v_account AND tag_label_key = public.serial_key(v_label)
       AND id <> v_asset.id;
    IF FOUND THEN
      RAISE EXCEPTION 'Tag label % is already on another item', v_label;
    END IF;
  END IF;

  -- Same for the chip id. A hardware uid is physically unique — two tags cannot
  -- share one — so a uid already on a DIFFERENT item means somebody has tagged
  -- the wrong thing, and letting it through would make both items resolve
  -- arbitrarily on a tap.
  --
  -- Enforced here rather than with a unique index on purpose: an index would
  -- have to hold for rows already in the live database, and there is no
  -- guarantee it does. Refusing new duplicates fixes the problem going forward
  -- without a migration that can fail on data nobody has looked at.
  IF v_uid IS NOT NULL THEN
    SELECT id INTO v_clash FROM public.assets
     WHERE account_id = v_account
       AND upper(regexp_replace(coalesce(nfc_tag_uid,''), '[^A-Fa-f0-9]', '', 'g'))
         = upper(regexp_replace(v_uid, '[^A-Fa-f0-9]', '', 'g'))
       AND coalesce(nfc_tag_uid,'') <> ''
       AND id <> v_asset.id;
    IF FOUND THEN
      RAISE EXCEPTION 'That tag is already on another item';
    END IF;
  END IF;

  -- The URL is rebuilt server-side rather than trusted from the payload. A
  -- client that sent a link to somewhere else would otherwise make this table
  -- claim we wrote it.
  v_url := coalesce(public.fp_tag_url(v_asset.public_ref, v_asset.serial_raw), v_url);

  INSERT INTO public.fp_tag_writes (
    account_id, asset_id, client_id, tag_label, nfc_tag_uid, tag_url,
    serial_num, public_ref, prev_label, prev_uid, written_by)
  VALUES (
    v_account, v_asset.id, v_client, v_label, v_uid, v_url,
    v_asset.serial_raw, v_asset.public_ref, v_asset.tag_label, v_asset.nfc_tag_uid, v_user)
  ON CONFLICT (account_id, client_id) WHERE client_id IS NOT NULL
    DO UPDATE SET written_at = public.fp_tag_writes.written_at
  RETURNING id INTO v_id;

  -- The item learns its new tag. Only ever set, never cleared by a write that
  -- knew less: a phone that could not read the chip id must not wipe the one
  -- already on record.
  UPDATE public.assets SET
    tag_label   = coalesce(v_label, tag_label),
    nfc_tag_uid = coalesce(v_uid, nfc_tag_uid),
    tag_url     = v_url,
    updated_at  = now()
   WHERE id = v_asset.id;

  RETURN json_build_object(
    'id', v_id, 'asset_id', v_asset.id,
    'tag_label', coalesce(v_label, v_asset.tag_label),
    'tag_url', v_url);
END;
$$;


--
-- Name: record_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_inspection(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_account  uuid;
  v_serial   text := trim(coalesce(p->>'serial_num', ''));
  v_date     date := coalesce((p->>'inspection_date')::date, current_date);
  v_asset    uuid;
  v_prev     public.inspections%ROWTYPE;
  v_id       uuid;
  v_version  integer := 1;
  v_rep      text;
  v_who      text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_serial = '' THEN RAISE EXCEPTION 'A serial number is required'; END IF;

  -- Follows the account being acted as; identical when not impersonating.
  v_account := public.my_account_id();
  IF v_account IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  -- Responsible rep comes from the account's lead, never from the payload: a
  -- sub-tech's device must not be able to claim a different rep number.
  v_rep := public.account_rep_number(v_account);

  SELECT coalesce(nullif(p->>'tech_name', ''), u.name, u.email)
    INTO v_who FROM public.users u WHERE u.id = v_user_id;
  v_who := coalesce(v_who, nullif(p->>'tech_name', ''), 'Lia Import');

  INSERT INTO public.assets (account_id, kind, serial_raw, serial_key)
  VALUES (v_account, coalesce(p->>'kind', 'ladder'), v_serial, public.serial_key(v_serial))
  ON CONFLICT (account_id, kind, serial_key) DO NOTHING
  RETURNING id INTO v_asset;

  IF v_asset IS NULL THEN
    SELECT id INTO v_asset FROM public.assets
     WHERE account_id = v_account
       AND kind = coalesce(p->>'kind', 'ladder')
       AND serial_key = public.serial_key(v_serial);
  END IF;

  SELECT * INTO v_prev FROM public.inspections
   WHERE asset_id = v_asset AND inspection_date = v_date AND is_current AND NOT is_deleted
   FOR UPDATE;

  IF FOUND THEN
    v_version := v_prev.version + 1;
    UPDATE public.inspections SET is_current = false, updated_at = now() WHERE id = v_prev.id;
  END IF;

  INSERT INTO public.inspections (
    serial_num, inspection_date, tech_name, work_order_id, next_due_date, notes,
    brand, type, length, account_id, asset_id, tech_user_id,
    version, supersedes, is_current, source, captured_at,
    lubricated, has_leveler, has_claw, has_vrung,
    rep_number, collected_by, collector_name, parts
  ) VALUES (
    v_serial, v_date, v_who,
    coalesce(nullif(p->>'work_order_id', ''), v_prev.work_order_id),
    coalesce((p->>'next_due_date')::date, v_date + interval '1 year'),
    coalesce(nullif(p->>'notes',  ''), v_prev.notes),
    coalesce(nullif(p->>'brand',  ''), v_prev.brand),
    coalesce(nullif(p->>'type',   ''), v_prev.type),
    coalesce(nullif(p->>'length', ''), v_prev.length),
    v_account, v_asset, v_user_id,
    v_version, v_prev.id, true,
    coalesce(p->>'source', 'office'),
    coalesce((p->>'captured_at')::timestamptz, now()),
    coalesce((p->>'lubricated')::boolean,  v_prev.lubricated),
    coalesce((p->>'has_leveler')::boolean, v_prev.has_leveler),
    coalesce((p->>'has_claw')::boolean,    v_prev.has_claw),
    coalesce((p->>'has_vrung')::boolean,   v_prev.has_vrung),
    v_rep, v_user_id, v_who,
    -- The parts a tech tapped on the phone. Without them a field record
    -- imports into BSI as a ladder with no line items, which is a ladder
    -- nobody can bill for.
    coalesce(p->'parts', v_prev.parts)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: record_inspections(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_inspections(p jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE rec jsonb; n integer := 0;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(p) LOOP
    PERFORM public.record_inspection(rec);
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$$;


--
-- Name: remove_crew_member(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_crew_member(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_account uuid;
  v_role    text;
  v_user    uuid := nullif(p->>'user_id', '')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason', '')), '');
  v_target  public.account_members%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_account := public.my_account_id();
  IF v_account IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  -- Acting as a subcontractor is acting as their lead, and the session was
  -- already gated on being one. Signed in as yourself, you must be the lead.
  IF NOT public.is_impersonating() THEN
    SELECT role INTO v_role FROM public.account_members
     WHERE user_id = v_caller AND removed_at IS NULL;
    IF v_role IS DISTINCT FROM 'lead' THEN
      RAISE EXCEPTION 'Only a lead can remove somebody from the crew';
    END IF;
  END IF;

  IF v_user IS NULL THEN RAISE EXCEPTION 'user_id is required'; END IF;
  IF v_user = v_caller THEN
    RAISE EXCEPTION 'You cannot remove yourself. Somebody else would have to let you back in.';
  END IF;

  SELECT * INTO v_target FROM public.account_members WHERE user_id = v_user;
  IF NOT FOUND OR v_target.account_id <> v_account THEN
    RAISE EXCEPTION 'That person is not on this account.';
  END IF;
  IF v_target.role = 'lead' THEN
    RAISE EXCEPTION 'A lead cannot be removed here: their number is the responsible technician on every certificate this account issues.';
  END IF;
  IF v_target.removed_at IS NOT NULL THEN
    RETURN json_build_object('removed', false, 'reason', 'already removed',
                             'removed_at', v_target.removed_at);
  END IF;

  UPDATE public.account_members
     SET removed_at = now(), removed_by = v_caller, removed_reason = v_reason
   WHERE user_id = v_user;

  RETURN json_build_object(
    'removed', true,
    'user_id', v_user,
    'records_kept', (SELECT count(*) FROM public.inspections WHERE collected_by = v_user)
                  + (SELECT count(*) FROM public.fp_inspections WHERE collected_by = v_user));
END;
$$;


--
-- Name: reply_support_ticket(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reply_support_ticket(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user   uuid := auth.uid();
  v_dev    boolean := public.is_developer();
  v_ticket uuid := nullif(p->>'ticket_id','')::uuid;
  v_body   text := nullif(btrim(coalesce(p->>'body','')), '');
  v_client uuid := nullif(p->>'client_id','')::uuid;
  v_who    text;
  v_role   text;
  v_t      public.support_tickets%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_body IS NULL THEN RAISE EXCEPTION 'A message is required'; END IF;

  IF v_ticket IS NULL AND nullif(p->>'ref','') IS NOT NULL THEN
    SELECT id INTO v_ticket FROM public.support_tickets WHERE ref = upper(p->>'ref');
  END IF;

  SELECT * INTO v_t FROM public.support_tickets WHERE id = v_ticket;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such ticket'; END IF;

  -- SECURITY DEFINER bypasses RLS, so the check is made explicitly here.
  IF NOT v_dev AND v_t.created_by IS DISTINCT FROM v_user THEN
    RAISE EXCEPTION 'That is not your ticket';
  END IF;

  IF v_client IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.support_messages WHERE client_id = v_client) THEN
    RETURN json_build_object('ticket_id', v_ticket, 'duplicate', true);
  END IF;

  v_role := CASE WHEN v_dev THEN 'developer' ELSE 'reporter' END;
  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = v_user;

  INSERT INTO public.support_messages (ticket_id, client_id, author_id, author_role, author_name, body)
  VALUES (v_ticket, v_client, v_user, v_role, v_who, v_body);

  UPDATE public.support_tickets SET
    last_message_at  = now(),
    updated_at       = now(),
    -- A developer's reply is what makes the tech's copy light up, and vice
    -- versa. A resolved ticket that gets a new reply is open again: the tech
    -- saying "still broken" must not be filed as closed.
    status = CASE
               WHEN v_dev AND status IN ('new', 'open') THEN 'answered'
               WHEN NOT v_dev AND status IN ('resolved', 'wont_fix', 'answered') THEN 'open'
               ELSE status
             END,
    unread_reporter  = CASE WHEN v_dev THEN true  ELSE unread_reporter  END,
    unread_developer = CASE WHEN v_dev THEN unread_developer ELSE true  END
  WHERE id = v_ticket;

  SELECT * INTO v_t FROM public.support_tickets WHERE id = v_ticket;
  RETURN row_to_json(v_t);
END;
$$;


--
-- Name: request_ip(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_ip() RETURNS inet
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  hdrs json;
  raw  text;
BEGIN
  BEGIN
    hdrs := nullif(current_setting('request.headers', true), '')::json;
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
  IF hdrs IS NULL THEN RETURN NULL; END IF;

  raw := coalesce(hdrs->>'x-forwarded-for', hdrs->>'cf-connecting-ip', hdrs->>'x-real-ip');
  IF raw IS NULL OR btrim(raw) = '' THEN RETURN NULL; END IF;
  raw := btrim(split_part(raw, ',', 1));
  -- An address with a port, or anything malformed, must not raise: this runs on
  -- every public page view and a throw would break the certificate itself.
  raw := regexp_replace(raw, ':\d+$', '');
  BEGIN
    RETURN raw::inet;
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
END;
$_$;


--
-- Name: require_lead(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_lead() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid; v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT account_id, role INTO v_account, v_role
    FROM public.account_members WHERE user_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;
  IF v_role <> 'lead' THEN
    RAISE EXCEPTION 'Only a lead technician can change the catalogue';
  END IF;
  RETURN v_account;
END;
$$;


--
-- Name: require_lead_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_lead_account() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT role INTO v_role FROM public.account_members
   WHERE user_id = auth.uid() AND removed_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;
  IF v_role <> 'lead' THEN
    RAISE EXCEPTION 'Only a lead technician can correct field records';
  END IF;
  RETURN public.my_account_id();
END;
$$;


--
-- Name: restore_crew_member(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_crew_member(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_account uuid;
  v_role    text;
  v_user    uuid := nullif(p->>'user_id', '')::uuid;
  v_target  public.account_members%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_account := public.my_account_id();
  IF v_account IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;

  IF NOT public.is_impersonating() THEN
    SELECT role INTO v_role FROM public.account_members
     WHERE user_id = v_caller AND removed_at IS NULL;
    IF v_role IS DISTINCT FROM 'lead' THEN
      RAISE EXCEPTION 'Only a lead can put somebody back on the crew';
    END IF;
  END IF;

  SELECT * INTO v_target FROM public.account_members WHERE user_id = v_user;
  IF NOT FOUND OR v_target.account_id <> v_account THEN
    RAISE EXCEPTION 'That person is not on this account.';
  END IF;

  UPDATE public.account_members
     SET removed_at = NULL, removed_by = NULL, removed_reason = NULL
   WHERE user_id = v_user;

  RETURN json_build_object('restored', true, 'user_id', v_user);
END;
$$;


--
-- Name: restore_fp_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_fp_inspection(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := nullif(p->>'inspection_id','')::uuid;
  v_row     public.fp_inspections%ROWTYPE;
  v_who     text;
BEGIN
  SELECT * INTO v_row FROM public.fp_inspections
   WHERE id = v_id AND account_id = v_account FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such inspection'; END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  -- Only one current row per item and date — the partial unique index enforces
  -- it, so anything newer stands down first.
  UPDATE public.fp_inspections SET is_current = false, updated_at = now()
   WHERE asset_id = v_row.asset_id AND inspection_date = v_row.inspection_date
     AND is_current AND NOT is_deleted;

  UPDATE public.fp_inspections
     SET is_deleted = false, is_current = true, updated_at = now()
   WHERE id = v_id;

  INSERT INTO public.fp_record_audit
    (account_id, asset_id, inspection_id, action, reason, actor_id, actor_name)
  VALUES (v_account, v_row.asset_id, v_id, 'restore',
          coalesce(nullif(p->>'reason',''), 'Restored'), auth.uid(), v_who);

  RETURN json_build_object('restored', v_id);
END;
$$;


--
-- Name: restore_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_inspection(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead_account();
  v_id      uuid := nullif(p->>'inspection_id','')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason','')), '');
  v_prev    public.inspections%ROWTYPE;
  v_who     text;
BEGIN
  IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why this record is being restored'; END IF;

  SELECT * INTO v_prev FROM public.inspections
   WHERE id = v_id AND account_id = v_account FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such inspection'; END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  -- Whatever else is standing for this serial on this date steps down: two
  -- current rows for one day is what every read in the app assumes cannot be.
  UPDATE public.inspections SET is_current = false, updated_at = now()
   WHERE account_id = v_account AND serial_num = v_prev.serial_num
     AND inspection_date = v_prev.inspection_date AND is_current AND id <> v_prev.id;

  UPDATE public.inspections
     SET is_deleted = false, is_current = true, updated_at = now()
   WHERE id = v_prev.id;

  INSERT INTO public.inspection_audit
    (account_id, inspection_id, serial_num, action, reason, before, after, actor_id, actor_name)
  VALUES (v_account, v_prev.id, v_prev.serial_num, 'restore', v_reason,
          row_to_json(v_prev)::jsonb,
          (SELECT row_to_json(i)::jsonb FROM public.inspections i WHERE i.id = v_prev.id),
          auth.uid(), v_who);

  RETURN (SELECT row_to_json(i) FROM public.inspections i WHERE i.id = v_prev.id);
END;
$$;


--
-- Name: save_fp_equipment_type(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_fp_equipment_type(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := nullif(p->>'id','')::uuid;
  v_name    text := nullif(trim(coalesce(p->>'name','')), '');
  v_slug    text := lower(regexp_replace(coalesce(nullif(trim(coalesce(p->>'slug','')), ''), v_name), '[^a-zA-Z0-9]+', '_', 'g'));
BEGIN
  IF v_name IS NULL THEN RAISE EXCEPTION 'An equipment type needs a name'; END IF;
  v_slug := trim(both '_' from v_slug);

  IF v_id IS NOT NULL THEN
    UPDATE public.fp_equipment_types
       SET name = v_name,
           sort_order = coalesce((p->>'sort_order')::integer, sort_order),
           is_active  = coalesce((p->>'is_active')::boolean, is_active)
     WHERE id = v_id AND account_id = v_account;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'That equipment type is not on your account — it is a shared type, edit its checklist to fork it';
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.fp_equipment_types (account_id, slug, name, sort_order, created_by)
  VALUES (v_account, v_slug, v_name, coalesce((p->>'sort_order')::integer, 999), auth.uid())
  ON CONFLICT (coalesce(account_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(slug))
  DO UPDATE SET name = EXCLUDED.name
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: save_fp_model(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_fp_model(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := nullif(p->>'id','')::uuid;
  v_mfr     text := nullif(trim(coalesce(p->>'manufacturer','')), '');
  v_model   text := nullif(trim(coalesce(p->>'model','')), '');
BEGIN
  IF v_mfr IS NULL OR v_model IS NULL THEN
    RAISE EXCEPTION 'A manufacturer and model are required';
  END IF;

  IF v_id IS NOT NULL THEN
    UPDATE public.fp_models
       SET manufacturer = v_mfr,
           model = v_model,
           item_type = nullif(p->>'item_type',''),
           has_impact_indicator = coalesce((p->>'has_impact_indicator')::boolean, false)
     WHERE id = v_id AND account_id = v_account;
    IF NOT FOUND THEN RAISE EXCEPTION 'That model is not on your account'; END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.fp_models (account_id, manufacturer, model, item_type,
                                has_impact_indicator, created_by)
  VALUES (v_account, v_mfr, v_model, nullif(p->>'item_type',''),
          coalesce((p->>'has_impact_indicator')::boolean, false), auth.uid())
  ON CONFLICT (coalesce(account_id, '00000000-0000-0000-0000-000000000000'::uuid),
               lower(manufacturer), lower(model))
  DO UPDATE SET item_type = EXCLUDED.item_type,
                has_impact_indicator = EXCLUDED.has_impact_indicator
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: save_job(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_job(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_uid     uuid := auth.uid();
  v_wo      text := coalesce(p->>'wo_number', '');
  v_key     text := public.wo_key(v_wo);
  v_scope   text := coalesce(p->>'scope', 'ladder');
  v_wo_id   uuid;
  v_job     uuid;
  v_ids     uuid[];
BEGIN
  IF v_key = '' THEN RAISE EXCEPTION 'A work order number is required'; END IF;
  IF v_scope NOT IN ('ladder', 'fall_protection') THEN
    RAISE EXCEPTION 'Unknown scope: %', v_scope;
  END IF;

  -- The work order row may already exist from an import; this must not disturb
  -- its billing state, so it is INSERT ... DO NOTHING and never an UPDATE.
  INSERT INTO public.work_orders (account_id, wo_number, wo_key, scope, created_by)
  VALUES (v_account, v_wo, v_key, v_scope, v_uid)
  ON CONFLICT (account_id, wo_key) DO NOTHING
  RETURNING id INTO v_wo_id;
  IF v_wo_id IS NULL THEN
    SELECT id INTO v_wo_id FROM public.work_orders
     WHERE account_id = v_account AND wo_key = v_key;
  END IF;

  INSERT INTO public.jobs (
    account_id, work_order_uuid, wo_number, wo_key, scope,
    title, site, notes, due_date, assign_all, share_peer_work, created_by)
  VALUES (
    v_account, v_wo_id, v_wo, v_key, v_scope,
    nullif(p->>'title', ''), nullif(p->>'site', ''), nullif(p->>'notes', ''),
    (nullif(p->>'due_date', ''))::date,
    coalesce((p->>'assign_all')::boolean, false),
    coalesce((p->>'share_peer_work')::boolean, false),
    v_uid)
  -- Every field is updated ONLY if the payload named it. Assigning
  -- `excluded.x` unconditionally would mean editing a job's notes from a screen
  -- that does not show the sharing toggle silently switched sharing back off —
  -- which is how a lead ends up revoking peer visibility without touching it.
  -- Same reasoning as the assignees block below.
  ON CONFLICT (account_id, wo_key) DO UPDATE SET
    title           = CASE WHEN p ? 'title'           THEN excluded.title           ELSE public.jobs.title END,
    site            = CASE WHEN p ? 'site'            THEN excluded.site            ELSE public.jobs.site END,
    notes           = CASE WHEN p ? 'notes'           THEN excluded.notes           ELSE public.jobs.notes END,
    due_date        = CASE WHEN p ? 'due_date'        THEN excluded.due_date        ELSE public.jobs.due_date END,
    scope           = CASE WHEN p ? 'scope'           THEN excluded.scope           ELSE public.jobs.scope END,
    assign_all      = CASE WHEN p ? 'assign_all'      THEN excluded.assign_all      ELSE public.jobs.assign_all END,
    share_peer_work = CASE WHEN p ? 'share_peer_work' THEN excluded.share_peer_work ELSE public.jobs.share_peer_work END,
    updated_at      = now()
  RETURNING id INTO v_job;

  -- Assignees are replaced wholesale when the key is present, and left alone
  -- when it is absent — so editing a job's notes from a screen that does not
  -- show the assignee list cannot silently unassign everybody.
  IF p ? 'assignees' THEN
    SELECT coalesce(array_agg(x::uuid), '{}') INTO v_ids
      FROM jsonb_array_elements_text(p->'assignees') x;

    -- Only members of this account. A user id from outside it would create an
    -- assignment nobody in the company can see or clear.
    DELETE FROM public.job_assignees ja WHERE ja.job_id = v_job
      AND NOT (ja.user_id = ANY (v_ids));
    INSERT INTO public.job_assignees (job_id, user_id, assigned_by)
    SELECT v_job, m.user_id, v_uid
      FROM public.account_members m
     WHERE m.account_id = v_account AND m.user_id = ANY (v_ids)
    ON CONFLICT (job_id, user_id) DO NOTHING;
  END IF;

  RETURN public.job_detail(v_job);
END;
$$;


--
-- Name: save_known_network(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_known_network(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.my_account_id();
  v_id      uuid := nullif(p->>'id','')::uuid;
  v_row     public.known_networks%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.account_members
                  WHERE user_id = auth.uid() AND role = 'lead') THEN
    RAISE EXCEPTION 'Only a lead technician can label networks';
  END IF;

  IF v_id IS NOT NULL THEN
    UPDATE public.known_networks
       SET cidr = (p->>'cidr')::cidr, label = p->>'label',
           kind = coalesce(nullif(p->>'kind',''), 'office')
     WHERE id = v_id AND account_id = v_account
    RETURNING * INTO v_row;
    IF NOT FOUND THEN RAISE EXCEPTION 'No such network'; END IF;
  ELSE
    INSERT INTO public.known_networks (account_id, cidr, label, kind)
    VALUES (v_account, (p->>'cidr')::cidr, p->>'label',
            coalesce(nullif(p->>'kind',''), 'office'))
    RETURNING * INTO v_row;
  END IF;
  RETURN row_to_json(v_row);
END;
$$;


--
-- Name: serial_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.serial_key(p_serial text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT upper(regexp_replace(coalesce(p_serial, ''), '[^A-Za-z0-9]', '', 'g'));
$$;


--
-- Name: set_photo_expiry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_photo_expiry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_days integer;
BEGIN
  IF NEW.expires_at IS NULL THEN
    SELECT coalesce(value::integer, 730) INTO v_days
      FROM public.app_settings WHERE key = 'photo_retention_days';
    NEW.expires_at := coalesce(NEW.uploaded_at, now()) + make_interval(days => coalesce(v_days, 730));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_support_ticket_status(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_support_ticket_status(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket uuid := nullif(p->>'ticket_id','')::uuid;
  v_status text := nullif(p->>'status','');
  v_t      public.support_tickets%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_developer() THEN RAISE EXCEPTION 'Only the developer can change a ticket status'; END IF;
  IF v_status NOT IN ('new','open','answered','resolved','wont_fix') THEN
    RAISE EXCEPTION 'Unknown status: %', coalesce(v_status, '(null)');
  END IF;

  UPDATE public.support_tickets
     SET status = v_status, updated_at = now(), unread_reporter = true
   WHERE id = v_ticket
  RETURNING * INTO v_t;

  IF NOT FOUND THEN RAISE EXCEPTION 'No such ticket'; END IF;
  RETURN row_to_json(v_t);
END;
$$;


--
-- Name: set_work_order_archived(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_work_order_archived(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead_account();
  v_wo      text := nullif(btrim(coalesce(p->>'work_order_id','')), '');
  v_on      boolean := coalesce((p->>'archived')::boolean, true);
  v_key     text;
  v_scope   text := coalesce(nullif(p->>'scope',''), 'ladder');
  v_id      uuid;
BEGIN
  IF v_wo IS NULL THEN RAISE EXCEPTION 'A work order number is required'; END IF;
  v_key := public.wo_key(v_wo);

  INSERT INTO public.work_orders (account_id, wo_number, wo_key, scope, created_by)
  VALUES (v_account, v_wo, v_key, v_scope, auth.uid())
  ON CONFLICT (account_id, wo_key) DO NOTHING;

  UPDATE public.work_orders
     SET archived_at = CASE WHEN v_on THEN now() ELSE NULL END,
         archived_by = CASE WHEN v_on THEN auth.uid() ELSE NULL END,
         updated_at  = now()
   WHERE account_id = v_account AND wo_key = v_key
  RETURNING id INTO v_id;

  RETURN json_build_object('work_order_id', v_wo, 'id', v_id, 'archived', v_on);
END;
$$;


--
-- Name: stamp_attribution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_attribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_num text; v_name text;
BEGIN
  IF NEW.rep_number IS NULL THEN
    SELECT r.rep_number, r.rep_name INTO v_num, v_name FROM public.account_rep(NEW.account_id) r;
    NEW.rep_number := v_num;
    IF NEW.rep_name IS NULL THEN NEW.rep_name := v_name; END IF;

  ELSIF NEW.rep_name IS NULL THEN
    SELECT coalesce(u.name, u.email) INTO NEW.rep_name
      FROM public.account_members m
      JOIN public.users u ON u.id = m.user_id
     WHERE m.rep_number = NEW.rep_number
     ORDER BY (m.account_id = NEW.account_id) DESC
     LIMIT 1;

    IF NEW.rep_name IS NULL THEN
      SELECT r.rep_name INTO NEW.rep_name FROM public.account_rep(NEW.account_id) r;
    END IF;
  END IF;

  IF NEW.verified_by IS NULL THEN
    NEW.verified_by := public.account_verifier(NEW.account_id);
  END IF;

  IF NEW.impersonation_id IS NULL THEN
    SELECT s.id INTO NEW.impersonation_id FROM public.active_impersonation() s;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: start_impersonation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_impersonation(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_real    uuid;
  v_role    text;
  v_target  uuid := (p->>'account_id')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason', '')), '');
  v_minutes integer := coalesce((p->>'minutes')::integer, 60);
  v_id      uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_target IS NULL THEN RAISE EXCEPTION 'account_id is required'; END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required: this is recorded against the work done as them.';
  END IF;

  -- The REAL account, deliberately: otherwise an active session could be used
  -- to start a further one, walking sideways through the tree.
  SELECT m.account_id, m.role INTO v_real, v_role
    FROM public.account_members m WHERE m.user_id = v_uid;
  IF v_real IS NULL THEN RAISE EXCEPTION 'No account — contact your administrator'; END IF;
  IF v_role IS DISTINCT FROM 'lead' THEN
    RAISE EXCEPTION 'Only a lead can act as another account';
  END IF;
  IF v_target = v_real THEN
    RAISE EXCEPTION 'That is your own account';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.account_descendants(v_real) d WHERE d.account_id = v_target) THEN
    RAISE EXCEPTION 'You can only act as an account beneath your own';
  END IF;

  v_minutes := greatest(1, least(v_minutes, 480));   -- 8 hours, hard ceiling

  -- One at a time. Two overlapping sessions would make "which account am I in"
  -- a matter of ordering.
  UPDATE public.impersonation_sessions SET ended_at = now()
   WHERE actor_user_id = v_uid AND ended_at IS NULL;

  INSERT INTO public.impersonation_sessions
    (actor_user_id, actor_account, account_id, account_name, reason, expires_at)
  VALUES (v_uid, v_real, v_target,
          (SELECT name FROM public.accounts WHERE id = v_target),
          v_reason, now() + make_interval(mins => v_minutes))
  RETURNING id INTO v_id;

  RETURN json_build_object(
    'id', v_id,
    'account_id', v_target,
    'account_name', (SELECT name FROM public.accounts WHERE id = v_target),
    'expires_at', (SELECT expires_at FROM public.impersonation_sessions WHERE id = v_id));
END;
$$;


--
-- Name: stop_impersonation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stop_impersonation() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  UPDATE public.impersonation_sessions SET ended_at = now()
   WHERE actor_user_id = auth.uid() AND ended_at IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN json_build_object('ended', v_n);
END;
$$;


--
-- Name: submit_support_ticket(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_support_ticket(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_account uuid;
  v_who     text;
  v_email   text;
  v_body    text := nullif(btrim(coalesce(p->>'body', '')), '');
  v_subject text := nullif(btrim(coalesce(p->>'subject', '')), '');
  v_client  uuid := nullif(p->>'client_id', '')::uuid;
  v_id      uuid;
  v_row     public.support_tickets%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_body IS NULL THEN RAISE EXCEPTION 'A message is required'; END IF;

  -- A retry of a queued submission returns the ORIGINAL ticket rather than
  -- filing a second one. Without this a flaky connection turns one complaint
  -- into five, and the developer cannot tell which is real.
  IF v_client IS NOT NULL THEN
    SELECT * INTO v_row FROM public.support_tickets WHERE client_id = v_client;
    IF FOUND THEN RETURN row_to_json(v_row); END IF;
  END IF;

  SELECT account_id INTO v_account FROM public.account_members WHERE user_id = v_user;
  SELECT coalesce(u.name, u.email), u.email INTO v_who, v_email
    FROM public.users u WHERE u.id = v_user;

  INSERT INTO public.support_tickets (
    client_id, account_id, created_by, reporter_name, reporter_email,
    kind, severity, subject, app, app_version, platform, screen, device
  ) VALUES (
    v_client, v_account, v_user, v_who, v_email,
    coalesce(nullif(p->>'kind',''), 'bug'),
    coalesce(nullif(p->>'severity',''), 'annoying'),
    -- A tech should never be blocked from reporting something because he did
    -- not think of a title. One is made from the message if he left it blank.
    coalesce(v_subject, left(regexp_replace(v_body, '\s+', ' ', 'g'), 72)),
    nullif(p->>'app',''), nullif(p->>'app_version',''),
    nullif(p->>'platform',''), nullif(p->>'screen',''),
    p->'device'
  )
  RETURNING id INTO v_id;

  INSERT INTO public.support_messages (ticket_id, client_id, author_id, author_role, author_name, body)
  VALUES (v_id, v_client, v_user, 'reporter', v_who, v_body);

  SELECT * INTO v_row FROM public.support_tickets WHERE id = v_id;
  RETURN row_to_json(v_row);
END;
$$;


--
-- Name: team_members(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_members() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid := public.my_account_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN (
    SELECT coalesce(json_agg(json_build_object(
             'user_id', u.id, 'name', u.name, 'email', u.email,
             'role', m.role, 'rep_number', m.rep_number,
             'removed_at', m.removed_at,
             'removed_reason', m.removed_reason)
             ORDER BY (m.removed_at IS NOT NULL), m.role, u.name), '[]'::json)
      FROM public.account_members m JOIN public.users u ON u.id = m.user_id
     WHERE m.account_id = v_account);
END;
$$;


--
-- Name: touch_asset_from_inspection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_asset_from_inspection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.assets SET updated_at = clock_timestamp() WHERE id = NEW.asset_id;
  RETURN NEW;
END;
$$;


--
-- Name: update_fp_asset(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_fp_asset(p jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid := public.require_lead();
  v_id      uuid := nullif(p->>'asset_id','')::uuid;
  v_reason  text := nullif(btrim(coalesce(p->>'reason','')), '');
  v_serial  text := nullif(btrim(coalesce(p->>'serial_raw','')), '');
  v_label   text := nullif(btrim(coalesce(p->>'tag_label','')), '');
  v_before  public.assets%ROWTYPE;
  v_who     text;
BEGIN
  IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why this item is being changed'; END IF;

  SELECT * INTO v_before FROM public.assets
   WHERE id = v_id AND account_id = v_account AND kind = 'fall_protection' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No such item'; END IF;

  IF v_serial IS NOT NULL AND public.serial_key(v_serial) <> v_before.serial_key
     AND EXISTS (SELECT 1 FROM public.assets
                  WHERE account_id = v_account AND kind = 'fall_protection'
                    AND serial_key = public.serial_key(v_serial)) THEN
    RAISE EXCEPTION 'Another item already has serial %', v_serial;
  END IF;

  IF v_label IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.assets
                  WHERE account_id = v_account
                    AND tag_label_key = public.serial_key(v_label)
                    AND id <> v_id) THEN
    RAISE EXCEPTION 'Tag label % is already on another item', v_label;
  END IF;

  SELECT coalesce(u.name, u.email) INTO v_who FROM public.users u WHERE u.id = auth.uid();

  UPDATE public.assets SET
    serial_raw  = coalesce(v_serial, serial_raw),
    serial_key  = CASE WHEN v_serial IS NULL THEN serial_key ELSE public.serial_key(v_serial) END,
    nfc_tag_uid = coalesce(nullif(p->>'nfc_tag_uid',''), nfc_tag_uid),
    tag_url     = coalesce(nullif(p->>'tag_url',''), tag_url),
    tag_label   = coalesce(v_label, tag_label),
    updated_at  = clock_timestamp()
  WHERE id = v_id;

  -- public_ref is deliberately NOT changeable. It is printed on tags already in
  -- the field; changing it would make every one of them point at nothing.

  INSERT INTO public.fp_record_audit
    (account_id, asset_id, action, reason, before, after, actor_id, actor_name)
  VALUES (v_account, v_id, 'asset_edit', v_reason,
          row_to_json(v_before)::jsonb,
          (SELECT row_to_json(a)::jsonb FROM public.assets a WHERE a.id = v_id),
          auth.uid(), v_who);

  RETURN (SELECT row_to_json(a) FROM public.assets a WHERE a.id = v_id);
END;
$$;


--
-- Name: urlencode_serial(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.urlencode_serial(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(string_agg(
    CASE WHEN ch ~ '[A-Za-z0-9._~-]' THEN ch
         ELSE '%' || upper(to_hex(ascii(ch))) END, ''), '')
  FROM regexp_split_to_table(coalesce(p, ''), '') AS ch
  WHERE ch <> '';
$$;


--
-- Name: visible_account_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.visible_account_ids() RETURNS TABLE(account_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.account_id FROM public.account_descendants(public.my_account_id()) d;
$$;


--
-- Name: wo_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wo_key(p_wo_number text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT upper(regexp_replace(coalesce(p_wo_number, ''), '[^A-Za-z0-9]', '', 'g'));
$$;


--
-- Name: account_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_members (
    user_id uuid NOT NULL,
    account_id uuid NOT NULL,
    role text DEFAULT 'lead'::text NOT NULL,
    desktop_access boolean DEFAULT true NOT NULL,
    rep_number text,
    invited_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    removed_at timestamp with time zone,
    removed_by uuid,
    removed_reason text,
    CONSTRAINT account_members_role_check CHECK ((role = ANY (ARRAY['lead'::text, 'tech'::text])))
);


--
-- Name: accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    plan text DEFAULT 'pay-per-use'::text NOT NULL,
    credits integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    parent_account_id uuid,
    CONSTRAINT accounts_parent_not_self CHECK (((parent_account_id IS NULL) OR (parent_account_id <> id)))
);


--
-- Name: app_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_settings (
    key text NOT NULL,
    value text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: assets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    kind text DEFAULT 'ladder'::text NOT NULL,
    serial_raw text NOT NULL,
    serial_key text NOT NULL,
    public_ref text DEFAULT public.gen_public_ref() NOT NULL,
    nfc_tag_uid text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tag_url text,
    tag_url_key text GENERATED ALWAYS AS (public.fp_tag_url_key(tag_url)) STORED,
    tag_label text,
    tag_label_key text GENERATED ALWAYS AS (public.serial_key(tag_label)) STORED,
    CONSTRAINT assets_kind_check CHECK ((kind = ANY (ARRAY['ladder'::text, 'fall_protection'::text])))
);


--
