--
-- Name: work_order_submissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.work_order_submissions WITH (security_invoker='true') AS
 SELECT i.account_id,
    i.work_order_id,
    i.collected_by,
    COALESCE(i.collector_name, 'Unknown'::text) AS collector_name,
    m.role AS collector_role,
    m.rep_number AS collector_rep_number,
    count(*) AS item_count,
    min(i.captured_at) AS first_captured_at,
    max(i.captured_at) AS last_captured_at
   FROM (public.inspections i
     LEFT JOIN public.account_members m ON ((m.user_id = i.collected_by)))
  WHERE (i.is_current AND (NOT i.is_deleted))
  GROUP BY i.account_id, i.work_order_id, i.collected_by, i.collector_name, m.role, m.rep_number;


