           FROM public.fp_models m
          WHERE ((m.id = t.model_id) AND public.can_use_catalog(m.account_id)))) OR (EXISTS ( SELECT 1
           FROM public.fp_equipment_types et
          WHERE ((et.id = t.equipment_type_id) AND public.can_use_catalog(et.account_id)))))))));


