  WHERE ((m.id = fp_check_templates.model_id) AND public.can_use_catalog(m.account_id)))) OR (EXISTS ( SELECT 1
   FROM public.fp_equipment_types et
  WHERE ((et.id = fp_check_templates.equipment_type_id) AND public.can_use_catalog(et.account_id))))));


